insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0701$t$, $t$Belleville Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate (Continued Certificate of Occupancy)$t$, $j$["Issued by: Township of Belleville Code Enforcement Department (Department of Community Development)","Contact: Nicholas DeAngelis, Director of Community Development (Construction Official: Chris Souza; Zoning Official: Brian Banda) · 973-450-3410 · ndeangelis@bellevillenj.org","How to apply: Download the Residential Resale Certificate Application from the Township forms page (Department of Community Development). The packet includes the resale certificate application, a Residential-Resale zoning permit and the smoke detector / carbon monoxide compliance application. Submit to the Code Enforcement Department, 152 Washington Avenue, Belleville, NJ 07109, with payment by money order or check (the form has an M.O. or Check # line). Extended hours for submission and pick up of the Continued Certificate of Occupancy were announced for the 2nd and 4th Wednesday of each month until 6:00 PM (2019 notice).","Inspection by Code Enforcement (the form has spaces for an inspection date and a re-inspection date)","Zoning permit, Residential-Resale type ($100.00), included in the resale application packet","Smoke detector / carbon monoxide compliance application (Ordinance #2572), included in the resale application packet","Smoke alarms on every level and outside each separate sleeping area; existing hardwired systems kept; 10-year sealed battery alarms where not hardwired; alarms no more than 10 years old","Carbon monoxide alarms within 10 feet of sleeping areas (checklist says on all levels); not required if no fuel-burning appliances and no attached garage","Portable fire extinguisher within 10 feet of the kitchen, 2A-10B:C, no more than 10 pounds, mounted with top no more than 5 feet off the floor, tagged within 12 months or with a recent purchase receipt (form still lists it)","Exterior free of trash, debris, high grass and weeds; foundation and exterior walls in good repair; gutters and downspouts working","Fences, sheds, pools and decks in good condition with a permit on file","Handrails on 4 or more risers; guardrails on open stairs, landings, balconies and decks","Water heater relief tail pipe no more than 6 inches off the ground; outlet and switch covers secured; GFCI outlets in kitchens and baths; hard metal dryer duct","Basement renovations, additions and remodels without township records are subject to permits and inspections","Application asks for buyer name and contact and the purchase price","Also: Zoning permit (Residential-Resale): The resale packet includes a Zoning Permit application with the Residential-Resale type checked, fee $100.00, reviewed by the Zoning Official.","Also: Permits on file for fences, sheds, pools, decks and basement work: The resale checklist says fences, sheds, pools and decks must have a permit on file, and basement renovations, additions and remodels without township records are subject to permits and inspections."]$j$::jsonb, $j$[{"label":"Residential resale certificate, one-family or condo","amount":"$225.00"},{"label":"Residential resale certificate, two-family","amount":"$300.00"},{"label":"Residential resale certificate, each additional unit","amount":"$50.00"},{"label":"Zoning permit (Residential-Resale), part of the resale packet","amount":"$100.00"}]$j$::jsonb, $t$https://www.bellevillenj.org/_Content/pdf/forms/RESIDENTIAL-RESALE-CERTIFICATE-APPLICATION.pdf$t$, $t$https://www.bellevillenj.org/Departments/department-of-community-development$t$, $j$[{"url":"https://www.bellevillenj.org/_Content/pdf/forms/RESIDENTIAL-RESALE-CERTIFICATE-APPLICATION.pdf","label":"Official source (bellevillenj.org)"},{"url":"https://www.bellevillenj.org/News/View/1008/extended-night-hours-for-the-building-and-code-enforcement-department","label":"Official source (bellevillenj.org)"},{"url":"https://ecode360.com/36464465","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$CODE ENFORCEMENT DEPARTMENT APPLICATION FOR A RESIDENTIAL RESALE CERTIFICATE$t$, $t$d1fc1b61f40719ee4679f3c2d60ed62fb4e8277b35809b446ee53081813fd459$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":9,"q_ok":2,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0701.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0701.json$t$, true),
  ($t$0701$t$, $t$Belleville Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Belleville Code Enforcement Department (Smoke Detector/Carbon Monoxide Compliance, Ordinance #2572) (town fire bureau)","Contact: 973-450-3410","How to apply: Fill out the Smoke Detector/Carbon Monoxide Compliance Application (Ordinance #2572) that is part of the Residential Resale Certificate Application packet and submit it to the Code Enforcement Department, 152 Washington Avenue, (973) 450-3410. The owner or the purchaser may request it.","Fire official in the NJ state directory, updated 9/30/2025: John Olivieri · (973) 450-3366 · jolivieri@bellevillenj.org","Smoke alarms on every level (including basements and finished attics) and outside each separate sleeping area; unfinished attics and crawl spaces excluded","Keep existing hardwired or interconnected systems; 10-year sealed battery single-station alarms where not hardwired; alarms no more than 10 years old","Carbon monoxide alarms within 10 feet of all sleeping areas; not required if there are no fuel-burning appliances and no attached garage","Portable fire extinguisher within 10 feet of the kitchen, UL listed 2A-10B:C, no more than 10 pounds, mounted on its bracket with the top no more than 5 feet off the floor, serviced and tagged by a certified NJ contractor within 12 months or with a recent purchase receipt (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector / carbon monoxide compliance certificate, one-family","amount":"$25.00"},{"label":"Smoke detector / carbon monoxide compliance certificate, two-family","amount":"$50.00"}]$j$::jsonb, $t$https://www.bellevillenj.org/_Content/pdf/forms/RESIDENTIAL-RESALE-CERTIFICATE-APPLICATION.pdf$t$, $t$https://www.bellevillenj.org/Departments/department-of-community-development$t$, $j$[{"url":"https://www.bellevillenj.org/_Content/pdf/forms/RESIDENTIAL-RESALE-CERTIFICATE-APPLICATION.pdf","label":"Official source (bellevillenj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$SMOKE DETECTOR/CARBON MONOXIDE COMPLIANCE APPLICATION ORDINANCE #2572$t$, $t$9bcd5da5aa016aedc61c20a2a2721b8d96026dce6b9da8865ac2ee3710d00bff$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":9,"q_ok":2,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0701.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0701.json$t$, true),
  ($t$0702$t$, $t$Bloomfield Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Transfer of Property Title (TOP), formerly called the Continuing (Continued) Certificate of Occupancy$t$, $j$["Issued by: Township of Bloomfield Fire Department, Fire Administration (Fire Prevention Bureau)","Contact: Vincent Colavitti, Fire Official (NJ DCA fire directory) · 973-680-4153 · vcolavitti@bloomfieldtwpnj.com","Apply: Application must be submitted 30 days before the closing date","How to apply: Fill out the Transfer of Property Title Application (buyer and seller details, closing date, whether it will be a rental) and submit it to the Fire Department, Fire Administration, 375 Franklin Street, Bloomfield, NJ 07003, at least 30 days before closing. Payment by check, money order or credit card. Questions: 973-680-4153.","Valid for: Six months","General inspection of the visible parts of the building for code violations and unsafe conditions (fire, electrical, plumbing, building, property and grounds checklist)","Smoke and CO alarms on each floor and near all bedrooms; battery smoke alarms must be 10-year sealed units unless hardwired, and battery alarms cannot replace hardwired ones (the TOP inspection also serves as the state smoke/CO certificate)","All construction permits, past and present, must be closed","Proof that any lead or galvanized water service line on the property has been replaced (plumber inspection documents the line material)","A Township-approved water meter must be installed, even if the house is winterized","Sump pumps and downspouts must not be connected to the sanitary sewer; sump pumps must drain outside","Rental property registration up to date; if the home will be a rental it must be registered within six months of closing","Heating equipment and water heaters properly vented; pressure relief valve discharge pipe; handrails on stairs with four or more risers; house properly numbered; sidewalks free of tripping hazards","Attached garage: fire-rated, self-closing door into the house","Portable fire extinguisher only for three-family and larger buildings","Also: Lead or galvanized water service line: Before the Transfer of Property Title is issued, the owner must prove that any lead service line on the property has been replaced; a licensed plumber inspects and documents the service line. Questions: Engineering Department, 973-680-4009.","Also: Water meter: A Township-approved water meter must be installed, even if the house is winterized.","Also: Sump pump and downspouts: The inspection checks that sump pumps and downspouts are not connected to the sanitary sewer.","Also: Open permits: All construction permits, past and present, must be closed before the Transfer of Property Title is issued."]$j$::jsonb, $j$[{"label":"Transfer of Property Title, single family residential dwelling","amount":"$200"},{"label":"Transfer of Property Title, two family residential dwelling","amount":"$260"},{"label":"Re-inspection after a failed inspection","amount":"$25"}]$j$::jsonb, $t$https://www.bloomfieldtwpnj.com/DocumentCenter/View/6941/CCO-Application-and-Information61220-PDF$t$, $t$https://www.bloomfieldtwpnj.com/176/Fire-Prevention$t$, $j$[{"url":"https://www.bloomfieldtwpnj.com/DocumentCenter/View/6941/CCO-Application-and-Information61220-PDF","label":"Official source (bloomfieldtwpnj.com)"},{"url":"https://www.bloomfieldtwpnj.com/m/faq?cat=16","label":"Official source (bloomfieldtwpnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$APPLICATION MUST BE SUBMITTED 30 DAYS PRIOR TO THE CLOSING DATE.$t$, $t$05183c2671e1e5f8d61107d3742543989156556474089f68206e306658c66bc5$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0702.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0702.json$t$, true),
  ($t$0702$t$, $t$Bloomfield Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bloomfield Fire Department, Fire Prevention Bureau (Fire Administration) (town fire bureau)","Contact: Vincent Colavitti, Fire Official · 973-680-4153 · vcolavitti@bloomfieldtwpnj.com","Apply: The smoke/CO check is part of the Transfer of Property Title inspection; apply 30 days before closing. A separate smoke/CO certificate is available if a lender insists.","How to apply: Normally no separate application: the Transfer of Property Title inspection serves as the CSACMAPFEC. If a lender insists on a separate certificate, ask the Fire Prevention Bureau at 973-680-4153.","Fire official in the NJ state directory, updated 8/24/2026: Vincent Colavitti · (973) 680-4053 · vcolavitti@bloomfieldtwpnj.com","Smoke and CO alarms on each floor and in the vicinity of all bedrooms","Battery smoke alarms must be 10-year sealed battery units unless hardwired; battery alarms cannot replace hardwired alarms","10-year sealed battery combination smoke/CO alarms are acceptable","Portable fire extinguisher required only for three-family and larger buildings (IFC 906.1), per the Township form","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Separate smoke and carbon monoxide detector certificate (only if the bank will not accept the Transfer of Property Title)","amount":"$35.00"}]$j$::jsonb, $t$https://www.bloomfieldtwpnj.com/DocumentCenter/View/6941/CCO-Application-and-Information61220-PDF$t$, $t$https://www.bloomfieldtwpnj.com/176/Fire-Prevention$t$, $j$[{"url":"https://www.bloomfieldtwpnj.com/m/faq?cat=16","label":"Official source (bloomfieldtwpnj.com)"},{"url":"https://www.bloomfieldtwpnj.com/DocumentCenter/View/6941/CCO-Application-and-Information61220-PDF","label":"Official source (bloomfieldtwpnj.com)"},{"url":"https://www.bloomfieldtwpnj.com/176/Fire-Prevention","label":"Official source (bloomfieldtwpnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This certificate will suffice for the smoke and carbon monoxide detector compliance.$t$, $t$a2cd33d9b16372eb3890a38e17a45bc630b00fdf1374cae15d2a2b128e659f73$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0702.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0702.json$t$, true),
  ($t$0703$t$, $t$Caldwell Borough$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Caldwell Construction Department (Property Maintenance / Zoning Official / Code Enforcement)","Contact: Mark Guiliano, Property Maintenance / Zoning Official / Code Enforcement (also the Borough fire official) · 973-403-4629 · fireofficial@caldwell-nj.com","Apply: Application must be submitted at least 10 days before closing","How to apply: Fill out the Borough's Application for Certificate of Occupancy/CCO (current owner, prospective owner, number of units, tentative closing date) and submit it with the fee to the Construction Department at Borough Hall, 80 Bloomfield Avenue, at least 10 days before closing. Pay by check.","Valid for: 90 days after issuance (Borough code, seen through search results)","Inspection of the home by the Borough before sale or transfer of title","All open permits must be closed before the certificate is issued","Smoke alarm, carbon monoxide alarm and fire extinguisher check is done as part of the CCO inspection (see fire certificate)","Borough also requires an explosive gas detector on each occupied level","Certificate is not issued until final payment is received and cleared","Also: Open permits: All open permits must be closed before the CCO is issued.","Also: Explosive gas detector: Caldwell requires a UL-listed explosive gas detector on each occupied level, checked at the CCO inspection."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy (CCO), per unit","amount":"$100"}]$j$::jsonb, $t$https://caldwell-nj.com/vertical/sites/%7B6BAC054F-223B-4082-A606-DE1D76D33F98%7D/uploads/CCO_Applicantion.pdf$t$, $t$https://caldwell-nj.com/construction$t$, $j$[{"url":"https://ecode360.com/28506499","label":"Official source (ecode360.com)"},{"url":"https://caldwell-nj.com/vertical/sites/%7B6BAC054F-223B-4082-A606-DE1D76D33F98%7D/uploads/CCO_Applicantion.pdf","label":"Official source (caldwell-nj.com)"},{"url":"https://caldwell-nj.com/vertical/sites/%7B6BAC054F-223B-4082-A606-DE1D76D33F98%7D/uploads/Uniform_fire_code_Required_Certificate_for_1_2_family_Dwellings.pdf","label":"Official source (caldwell-nj.com)"},{"url":"https://caldwell-nj.com/construction","label":"Official source (caldwell-nj.com)"}]$j$::jsonb, $t$No owner of any building, dwelling, or dwelling unit shall sell or transfer title of same without first obtaining a certificate of continued occupancy from the Construction Department of the Borough of Caldwell.$t$, $t$b345ec16ac7f95399fa6bd8a0213d78609920d9c90a5d4562cbffb1f75bcf8ba$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0703.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0703.json$t$, true),
  ($t$0703$t$, $t$Caldwell Borough$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Caldwell Fire Prevention Bureau (Fire Official Mark Guiliano), done as part of the CCO inspection (town fire bureau)","Contact: Mark Guiliano, Fire Official · 973-403-4629 · fireofficial@caldwell-nj.com","Apply: Done during the CCO inspection; CCO application must be in at least 10 days before closing. Fire inspections are scheduled Wednesday 10:00am-12:00pm per the Construction page.","How to apply: No separate application. The smoke detector, carbon monoxide, explosive gas and fire extinguisher certificate is issued with the CCO, at no additional cost. Questions: Fire Prevention Bureau, 973-403-4629.","Fire official in the NJ state directory (town), updated 7/26/2025: Mark Guiliano · (973) 661-1820 · fireofficial@caldwell-nj.com","Smoke alarm on each level including the basement (not unfinished attics), outside sleeping areas; 10-year sealed battery units where no hardwired system is required","Hardwired, interconnected systems required at construction or renovation must be in place and working; battery alarms not accepted in that case","Carbon monoxide alarm outside sleeping rooms on each level with bedrooms; combination smoke/CO allowed","Alarms must be within service life, UL approved, with fresh batteries; mounted with proper fasteners (no Velcro or tape)","Explosive gas detector on each occupied level (Borough requirement)","Two family homes also need smoke alarms at the top of each common stairwell","Class A-B-C fire extinguisher, no more than 10 lbs, mounted no higher than 48 inches in or within 10 feet of the kitchen (form still lists it)","Monitored low-voltage alarm systems must be put on test with the monitoring company before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://caldwell-nj.com/vertical/sites/%7B6BAC054F-223B-4082-A606-DE1D76D33F98%7D/uploads/CCO_Applicantion.pdf$t$, $t$https://caldwell-nj.com/construction$t$, $j$[{"url":"https://caldwell-nj.com/vertical/sites/%7B6BAC054F-223B-4082-A606-DE1D76D33F98%7D/uploads/Uniform_fire_code_Required_Certificate_for_1_2_family_Dwellings.pdf","label":"Official source (caldwell-nj.com)"},{"url":"https://caldwell-nj.com/faq","label":"Official source (caldwell-nj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$In Caldwell, a "Certificate Of Smoke Detector, Carbon Monoxide, Explosive Gas, and Portable Fire Extinguisher Compliance" is included as part of your CCO inspection at no additional cost.$t$, $t$130ec23cc1169bb4298561bcd765b7a2040196a7f5a59b0c3a94eac95ce48985$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0703.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0703.json$t$, true),
  ($t$0705$t$, $t$East Orange City$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Conformity (resale housing inspection)$t$, $j$["Issued by: City of East Orange Department of Code Enforcement, Division of Housing & Inspections (Public Officer)","Contact: Hassan Mateen, Acting Director, Department of Code Enforcement · 973-266-5320 · Hassan.Mateen@eastorange-nj.gov","Apply: The City inspects within 15 days of the request; the application says all inspections must be completed fifteen (15) working days prior to the closing date.","How to apply: Fill out the City's Application for Certificate of Conformity (Forms & Permits page, Housing & Inspections) and file it with the Department of Code Enforcement, Division of Housing & Inspections, 44 City Hall Plaza, East Orange. Pay by certified check or money order. Either the seller or the buyer may pay; the form asks who paid. Apply early enough for the inspection to be done 15 working days before closing.","Valid for: If violations will not be fixed before closing, a nonrenewable temporary certificate of conformity may be issued, valid for up to six months from the date of conveyance","Inspection by a City housing inspector for compliance with Chapter 159 (Housing Standards; Property Maintenance) before the sale closes","Building Division checks that there are no open permits and no elevator violations","All utilities must be operational at the time of inspection","Applicant affirms the property is connected to the public water supply through an East Orange Water Commission meter (or explains why not in writing)","If an LLC is the seller or buyer, the managing member's name is required; no P.O. boxes","As-is sales: attach the agreement of sale, signed by both seller and buyer, and acknowledge the violations to get a temporary certificate","Fees by certified check or money order","Also: Open permits and elevator violations: The Building Division checks for open permits and elevator violations as part of the certificate of conformity application.","Also: Public water connection: The applicant affirms the home is connected to the City's public water supply through an East Orange Water Commission meter, or explains in writing why not."]$j$::jsonb, $j$[{"label":"Certificate of conformity inspection, 1 and 2 dwelling units","amount":"$250"},{"label":"Second reinspection, 1 and 2 dwelling units","amount":"$100"},{"label":"Third and subsequent reinspections, 1 and 2 dwelling units","amount":"$150"}]$j$::jsonb, $t$https://www.eastorange-nj.gov/DocumentCenter/View/3559/Application-for-Certificate-of-Conformity-2026-Updated$t$, $t$https://www.eastorange-nj.gov/355/Forms-Permits$t$, $j$[{"url":"https://ecode360.com/9564316","label":"Official source (ecode360.com)"},{"url":"https://www.eastorange-nj.gov/DocumentCenter/View/3559/Application-for-Certificate-of-Conformity-2026-Updated","label":"Official source (eastorange-nj.gov)"},{"url":"https://www.eastorange-nj.gov/Directory.aspx","label":"Official source (eastorange-nj.gov)"}]$j$::jsonb, $t$It shall henceforth be unlawful for any owner and/or prospective purchaser of real property to sell, convey, deliver or transfer and for any purchaser to purchase, take title or possession of any building, premises or unoccupied/vacant lot until a certificate of conformity has been issued$t$, $t$18b6520eee311d190ed52cda46ec6880ed994781bb5949fed53a86d76f497eb6$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":2,"fee_bad":0,"fee_unchecked":5,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0705.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0705.json$t$, true),
  ($t$0705$t$, $t$East Orange City$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: East Orange Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Joseph Simmons, Fire Official (NJ DCA fire directory) · 973-266-5520 · joseph.simmons@eastorange-nj.gov","Apply: Fee depends on business days between the request and the change of occupant: more than 10 business days for the lowest fee. Smoke/CO inspections are scheduled Monday to Thursday, 9:30am to 3:30pm.","How to apply: Apply online through the Fire Department's portal (linked from the City's Forms & Permits page as 'Fire Dept. Inspections, Business/Property Registration, Permits & Fees') and choose 'New Smoke/CO Application'. For questions call the Fire Prevention Bureau at 973-266-5520.","Fire official in the NJ state directory, updated 4/15/2024: Joseph Simmons · (973) 266-5519 · joseph.simmons@eastorange-nj.gov","Smoke alarms, carbon monoxide alarms and a portable fire extinguisher as listed in the City code's certificate name (CSACMAPFEC) under N.J.A.C. 5:70-2.3 (the code still names the extinguisher)","Inspection by the East Orange Fire Prevention Bureau before the change of occupant","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, CO alarm and extinguisher certificate, request more than 10 business days before the change of occupant","amount":"$100"},{"label":"Request 4 to 10 business days before the change of occupant","amount":"$125"},{"label":"Request fewer than 4 business days before the change of occupant","amount":"$175"},{"label":"Recheck inspection","amount":"$50"}]$j$::jsonb, $t$https://geo.muniverse.us/prod1/portal/portal.jsp?c=127134&p=149980&g=149982$t$, $t$https://www.eastorange-nj.gov/161/Fire-Department$t$, $j$[{"url":"https://ecode360.com/45291038","label":"Official source (ecode360.com)"},{"url":"https://geo.muniverse.us/prod1/portal/portal.jsp?c=127134&p=149980&g=149982","label":"Official source (geo.muniverse.us)"},{"url":"https://www.eastorange-nj.gov/161/Fire-Department","label":"Official source (eastorange-nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certificate of smoke alarm, carbon monoxide alarm and portable fire extinguisher compliance (CSACMAPFEC). The application fee for a CSACMAPFEC, as required by N.J.S.A. 5:70-2.3, shall be based upon the amount of time remaining before the change of occupant is expected, as follows:$t$, $t$d185e3e119994842bc36f074795c68d786eb605ab14fce9ca015bee4b3bd3339$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":2,"fee_bad":0,"fee_unchecked":5,"quotes":16,"q_ok":10,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0705.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0705.json$t$, true),
  ($t$0706$t$, $t$Essex Fells Borough$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO) on a Re-Sale of a Residential Dwelling$t$, $j$["Issued by: Borough of Essex Fells Code Enforcement Department (Building and Zoning)","Contact: 973-226-3400 · BuildingTA@essexfellsboro.com","How to apply: Download the CCO - Home Sale Application from the Borough forms page (Building and Zoning) and submit it with a check to the Code Enforcement Department, 255 Roseland Avenue, Essex Fells, NJ 07021, (973) 226-3400, fax (973) 228-4439. The Building Department is part time; questions go to the Certified Technical Assistant at BuildingTA@essexfellsboro.com. Inspections cannot be scheduled by voice mail; call during regular business hours.","Inspection by the Borough (the form has a date of inspection line for office use)","Smoke detectors on each level including the basement near the stairs and within 10 feet of each bedroom; habitable attics need detection; replace if older than 10 years; UL listed","Carbon monoxide detectors on each level with bedrooms, outside of and within 10 feet of each bedroom, if the home has a fuel burning appliance and/or attached garage (checklist says replace if older than 5 years)","Portable ABC fire extinguisher, 2A:10B:C, 2 to 10 pounds, within 10 feet of the kitchen, mounted on its bracket with the top no higher than 5 feet (form still lists it)","Sump pump must discharge outside; storm water may not go into the sanitary sewer or onto a neighbor's property","Zoning compliance; no zoning certificate until all open building permits are closed","House numbers 4 to 8 inches high, Arabic, visible from the street, mounted 4 to 10 feet above grade on a contrasting background","Exterior free of trash, debris, high grass and weeds; foundation and exterior walls in good repair","Fences, sheds, pools and decks in good condition with a permit on file","Handrails on 3 or more risers; guardrails on open stairs, landings, balconies and decks","Water heater relief tail pipe no more than 6 inches off the ground; outlet and switch plate covers secured","Self-closing door from an attached garage to the house","Basement renovations, additions and remodels without township records are subject to permits and inspections","Application asks for buyer name and address, purchase price and closing date","Also: Final water meter reading: The Borough Water Department charges for a final reading of the meter for a house sale: 'Final reading of a meter for house sale: $100'.","Also: Open building permits: Open building permits must be closed by scheduling final inspections; no zoning certificate is issued until all open permits are closed.","Also: Sump pump discharge: If the house has a sump pump it must discharge outside; storm water may not go into the sanitary sewer or onto adjoining property. Checked as part of the CCO."]$j$::jsonb, $j$[{"label":"Continued certificate of occupancy on resale, one or two family","amount":"$125"}]$j$::jsonb, $t$https://www.essexfellsboro.com/_Content/pdf/forms/CCO-Home-Sale-Application.pdf$t$, $t$https://www.essexfellsboro.com/Departments/building-and-zoning$t$, $j$[{"url":"https://www.essexfellsboro.com/_Content/pdf/forms/CCO-Home-Sale-Application.pdf","label":"Official source (essexfellsboro.com)"},{"url":"https://www.essexfellsboro.com/Departments/building-and-zoning","label":"Official source (essexfellsboro.com)"}]$j$::jsonb, $t$APPLICATION FOR A CONTINUED CERTIFICATE OF OCCUPANCY ON A RE-SALE OF A RESIDENTIAL DWELLING$t$, $t$d202f997bb4301433b81cb9c47023bee0599de8b40721346afabbf9c67d6bdb7$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":8,"q_ok":4,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0706.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0706.json$t$, true),
  ($t$0706$t$, $t$Essex Fells Borough$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety (state is the fire code enforcing agency for Essex Fells) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official (NJ Division of Fire Safety), per state fire directory · 609-633-6132","How to apply: The state fire directory lists the NJ Division of Fire Safety, PO Box 809, Trenton NJ 08625-0809, (609) 633-6132, as the smoke detector compliance office for Essex Fells. Call the Division to request the certificate. Also ask the Borough Code Enforcement office whether its CCO inspection, which checks smoke and CO alarms, is accepted in place of a separate state certificate.","Fire official in the NJ state directory (NJ DCA, state), updated 9/10/2025: Louis Kilmer · (609)633-6132","Smoke alarms on each level and outside each sleeping area (Borough CCO checklist covers these)","Carbon monoxide alarms near sleeping areas where there is a fuel burning appliance or attached garage","Portable fire extinguisher near the kitchen (the Borough CCO form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/ANNOUNCEMENTS/DCA%20Advisory%20Bulletin%20for%20Licensure.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$LEAID: 0706-999 Essex Fells Boro SMOKE DETECTOR COMPLIANCE Name: NJ Division Fire Safety Enf Auth. State Addr: PO Box 809 Trenton NJ 08625-0809 Fire Official Louis Kilmer Phone (609) 633-6132$t$, $t$8ed03b41b1f9f3ccd0099cd17b11b61df3d2446c1b73e21f286ea2d6a5319437$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":8,"q_ok":4,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0706.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0706.json$t$, true),
  ($t$0707$t$, $t$Fairfield Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Reoccupancy (Residential Application, Certificate of Re-Occupancy)$t$, $j$["Issued by: Township of Fairfield (the code says the \"Township Official\"); the residential application is posted on the Fire Prevention Bureau forms page","Contact: 973-882-2700 ext. 2506 · fireprevention@fairfieldnj.org","Apply: The code says the Township Official shall inspect and issue within 10 days of receipt (search snippet)","How to apply: Fill out the Residential Application, Certificate of Re-Occupancy (PDF on the Fire Prevention forms page), mark Sale, and send it with the $125.00 fee. The form does not say where to file it; the Fire Prevention office (973-882-2700 ext. 2506, fireprevention@fairfieldnj.org) posts it, and the Building Department is at ext. 2503.","Valid for: One year once issued (code, search snippet)","Application with the $125.00 fee; mark Sale or Rental and give the date and time the premises can be inspected","Buyer's name, phone and email, number of new occupants and bedrooms, and names and relationship of the people moving in","Seller's name, phone and email and signature","Possible inspections by the Zoning Officer (zoning compliance) and the Construction Official (apparent Construction Code violations); the code also lists Tax Assessor, Board of Health, Fire Prevention, Property Maintenance Officer and Engineer","Violations found are noted on the certificate","Also: Zoning and construction check under the Certificate of Reoccupancy: The Zoning Officer may check zoning compliance and the Construction Official may check for apparent Construction Code violations as part of the Certificate of Reoccupancy (code text seen only through search results)."]$j$::jsonb, $j$[{"label":"Residential Certificate of Re-Occupancy (sale or rental)","amount":"$125.00"}]$j$::jsonb, $t$https://www.fairfieldtownshipnj.gov/DocumentCenter/View/290/Residential-Application-Certificate-of-Re-Occupancy-PDF$t$, $t$https://www.fairfieldtownshipnj.gov/177/Forms-Documents$t$, $j$[{"url":"https://www.fairfieldtownshipnj.gov/DocumentCenter/View/290/Residential-Application-Certificate-of-Re-Occupancy-PDF","label":"Official source (fairfieldtownshipnj.gov)"},{"url":"https://ecode360.com/35316176","label":"Official source (ecode360.com)"},{"url":"https://www.fairfieldtownshipnj.gov/177/Forms-Documents","label":"Official source (fairfieldtownshipnj.gov)"},{"url":"https://www.fairfieldtownshipnj.gov/164/Fire-Prevention","label":"Official source (fairfieldtownshipnj.gov)"}]$j$::jsonb, $t$RESIDENTIAL APPLICATION - CERTICATE OF RE-OCCUPANCY$t$, $t$a19d573a9359cd0005d7022a55e37685d6e2b1686ade2eed42f406de9716bed8$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0707.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0707.json$t$, true),
  ($t$0707$t$, $t$Fairfield Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Fairfield Fire Prevention Bureau (Township of Fairfield) (town fire bureau)","Contact: Joe Przybylinski, Fire Official · 973-882-2700 ext. 2506 · jprzybylinski@fairfieldnj.org","Apply: Fee depends on how many business days before the change of occupancy the request is received: more than 10 business days for the lowest fee. No specific inspection times are given.","How to apply: Fill out the Application for Certificate of Smoke Alarm, Carbon Monoxide Alarm and Secondary Power Source Identification Label Compliance (CSACMASPIL) with the closing date, block and lot, and owner contact, and pay the fee to the Township of Fairfield. When calling for the inspection have the owner's name as on the deed, address, block and lot, buyer's name and a contact phone. Fire Prevention, 230 Fairfield Road, Fairfield, NJ 07004, 973-882-2700 ext. 2506.","Fire official in the NJ state directory (town), updated 1/12/2026: Joseph Przybylinski, Sr. · (973) 882-2735 · jprzybylinski@fairfieldnj.org","Smoke alarms on each level of the home within 10 feet of every bedroom door between the door and the living area (not crawl spaces or unfinished attics with pull-down stairs); photoelectric type if within 10 feet of a kitchen","Basement alarm on the basement ceiling within three feet of the stairwell; alarms fixed with screws, not tape or Velcro","CO alarms required in units with a fuel-burning appliance, fireplace, woodstove or attached garage, centrally located outside each sleeping area within 10 feet of every bedroom door; UL 2034","Smoke and CO alarms must be less than 10 years old; single-station battery smoke alarms must be 10-year sealed battery alarms; existing hardwired alarms may not be replaced with battery alarms","Central station monitored fire alarm systems need an NFPA 72 test report and proof of monitoring, or the inspection fails","Secondary power source (solar PV, backup generator, home battery) warning label within 18 inches of the main electrical panel and electric meter (effective February 3, 2025)","Portable fire extinguisher (older Township form and the Smoke Detectors page still list it; the newer CSACMASPIL form does not)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, request received more than ten business days before the change of occupancy","amount":"$70"},{"label":"Request received four to ten business days before the change of occupancy","amount":"$95"},{"label":"Request received fewer than four business days before the change of occupancy","amount":"$161"}]$j$::jsonb, $t$https://www.fairfieldtownshipnj.gov/DocumentCenter/View/3095/Certificate-of-Smoke-Alarm-Carbon-Monoxide-Alarm-and-Secondary-Power-Source-Identification-Label-Compliance-CSACMASPILpdf$t$, $t$https://www.fairfieldtownshipnj.gov/184/Smoke-Detectors$t$, $j$[{"url":"https://www.fairfieldtownshipnj.gov/184/Smoke-Detectors","label":"Official source (fairfieldtownshipnj.gov)"},{"url":"https://www.fairfieldtownshipnj.gov/DocumentCenter/View/3095/Certificate-of-Smoke-Alarm-Carbon-Monoxide-Alarm-and-Secondary-Power-Source-Identification-Label-Compliance-CSACMASPILpdf","label":"Official source (fairfieldtownshipnj.gov)"},{"url":"https://www.fairfieldtownshipnj.gov/DocumentCenter/View/280/Cert-Smoke-Detector-Cm-Fire-Ext-PDF","label":"Official source (fairfieldtownshipnj.gov)"},{"url":"https://www.fairfieldtownshipnj.gov/164/Fire-Prevention","label":"Official source (fairfieldtownshipnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fee payable to Township of Fairfield.$t$, $t$c3b9809f63e942e8d105242958f055419b5fb257c9784bf13e7d22233b973db4$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0707.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0707.json$t$, true),
  ($t$0708$t$, $t$Glen Ridge Borough$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Zoning Compliance Certificate for residential property transfer$t$, $j$["Issued by: Borough of Glen Ridge, Director of Planning and Development","Contact: Erik DeLine, Director of Planning & Development · 973-748-8400 ext. 240 · eideline@glenridgenj.org","How to apply: The seller or owner (only) emails the Director of Planning and Development at eideline@glenridgenj.org to request the Certificate of Occupancy for the sale. The office is at the Glen Ridge Municipal Building, 825 Bloomfield Avenue, Room 101.","Seller or owner only must request it by email to the Director of Planning and Development","Zoning compliance inspection of the property before the sale","Smoke detector certification is handled on the same Borough page (see fire certificate)"]$j$::jsonb, $j$[{"label":"Zoning Compliance Certificate, residential property transfer","amount":"$175.00"},{"label":"Smoke detector certification (Borough fee schedule, Zoning section)","amount":"$75.00"}]$j$::jsonb, null, $t$https://www.glenridgenj.org/zoningcomp/$t$, $j$[{"url":"https://www.glenridgenj.org/zoningcomp/","label":"Official source (glenridgenj.org)"},{"url":"https://www.glenridgenj.org/wp-content/uploads/2026/01/Resolution-18-26-Fee-Schedule.pdf","label":"Official source (glenridgenj.org)"},{"url":"https://www.glenridgenj.org/planning-development/","label":"Official source (glenridgenj.org)"}]$j$::jsonb, $t$To obtain a Certificate of Occupancy for the sale of a house or transfer of a tenant, the SELLER / OWNER ONLY is to EMAIL the Director of Planning and Development at:$t$, $t$ccb63b16bef642fe09fac178ec051577982c6cc622092f88c9268cde71e1e6d2$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":9,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0708.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0708.json$t$, true),
  ($t$0708$t$, $t$Glen Ridge Borough$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Glen Ridge Planning and Development / Zoning (smoke certificate requested through the same Borough page); fire code enforcing agency is the Montclair Township Fire Department under a… (town fire bureau)","Contact: Justin Thompson, Fire Official (Montclair Fire Department, shared service for Glen Ridge) · 973-748-8400 ext. 240 · eideline@glenridgenj.org","Apply: Montclair's process asks for documents at least 10 days before closing; Glen Ridge did not post a lead time.","How to apply: Start with the Borough: the seller emails the Director of Planning and Development (eideline@glenridgenj.org), whose page covers both the zoning compliance and smoke certificate. The Montclair Fire Prevention Bureau (fireprevention@montclairnjusa.org, 973-509-4760 per state directory) is the listed fire code agency and can confirm who inspects.","Fire official in the NJ state directory, updated 9/5/2025: Justin Thompson · (973) 509-4760 · jthompson@montclairnjusa.org","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-2.3 for a 1-2 family sale (no Borough checklist found online)","Montclair Fire Prevention Bureau (the fire code agency for Glen Ridge) says fire extinguishers are no longer required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector certification (Borough fee schedule, Zoning section)","amount":"$75.00"}]$j$::jsonb, null, $t$https://www.glenridgenj.org/zoningcomp/$t$, $j$[{"url":"https://www.glenridgenj.org/zoningcomp/","label":"Official source (glenridgenj.org)"},{"url":"https://www.glenridgenj.org/wp-content/uploads/2026/01/Resolution-18-26-Fee-Schedule.pdf","label":"Official source (glenridgenj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.montclairnjusa.org/Government/Departments/Fire-Department/Inspections","label":"Official source (montclairnjusa.org)"}]$j$::jsonb, $t$Zoning Compliance & Smoke Certificate Requirements$t$, $t$7e753109a0bdd586391c7a8ec4679de865105aebfa8c5077645332f91f8d8f4f$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":9,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0708.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0708.json$t$, true),
  ($t$0710$t$, $t$Livingston Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Livingston Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Martin J. Chiarolanzio, Construction Code Official · 973-992-5000 ext. 5200 · building@livingstonnj.org","How to apply: No Township resale Certificate of Occupancy. The Township's FAQ says a C.O. is not required for the sale of a home; you need the smoke detector certification from the Livingston Fire Department (see fire certificate). The Building Department recommends calling well ahead of closing to check for open permits.","Also: Open permits check: The Building Department recommends calling 973-992-5000 ext. #5200 well before closing to find any open permits, which could slow the sale."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.livingstonnj.org/1776/Building$t$, $j$[{"url":"https://www.livingstonnj.org/Faq.aspx?QID=65","label":"Official source (livingstonnj.org)"},{"url":"https://www.livingstonnj.org/1776/Building","label":"Official source (livingstonnj.org)"}]$j$::jsonb, $t$No, a C.O. is not required.$t$, $t$ea1f9c4e99c81c1783f685d6fca76b672495fd48c5c230851933beb03ae427cc$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0710.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0710.json$t$, true),
  ($t$0710$t$, $t$Livingston Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Livingston Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Christopher C. Mullin, Fire Chief/Fire Official · 973-992-2373 · lfd@livingstonnj.org","Apply: Call to schedule at least 10 days before closing. Fees are paid at the inspection.","How to apply: Call the Livingston Fire Prevention Bureau at 973-992-2373, Monday through Friday (8:30 a.m. to 4:00 p.m.), to schedule the inspection at least 10 days before closing. Pay at the time of inspection by cash or check payable to the Township of Livingston (no credit cards). A Smoke Detector Waiver Request Form is posted for demolition properties.","Fire official in the NJ state directory, updated 1/21/2026: Christopher Mullin · (973) 992-2373 · cmullin@livingstonnj.org","Smoke detector on each level: basement at the bottom of the stairs, and each floor at the stairs or within 10 feet of bedrooms; attic not required","Battery smoke detectors must be 10-year sealed units; homes built with hardwired interconnected detectors cannot substitute battery or wireless units","Carbon monoxide detector(s) within 10 feet of all bedroom areas; battery, hardwired or plug-in allowed","All detectors UL listed and mounted with screws (no tape, Velcro, nails or picture hooks), except plug-in CO units","One ABC fire extinguisher, 2A:10B:C or greater, wall mounted about 5 feet off the floor in a visible spot in or within 10 feet of the kitchen, not in a cabinet or behind a door; one per kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and CO alarm certificate, 1 and 2 family, initial inspection","amount":"$75"},{"label":"Re-inspection after an unsuccessful initial inspection","amount":"$35"},{"label":"Waiver in lieu of smoke detector inspection (demolition properties only)","amount":"$25"}]$j$::jsonb, null, $t$https://www.livingstonnj.org/2046/Smoke-Detector-Requirements-for-Resident$t$, $j$[{"url":"https://www.livingstonnj.org/2046/Smoke-Detector-Requirements-for-Resident","label":"Official source (livingstonnj.org)"},{"url":"https://livingstonnj.org/DocumentCenter/View/35803/Fire-Prevention-Fees-PDF","label":"Official source (livingstonnj.org)"},{"url":"https://livingstonnj.org/DocumentCenter/View/35802/Residential-Smoke-Detector-Requirements-PDF","label":"Official source (livingstonnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This is required, and you will not be able to sell your home or allow a renter to occupy the premises until the property has passed the inspection.$t$, $t$5bed0abbcc4eafd9cc8ff96cf092ddea617f1a0fed9ceb8229ce7e66dfb9e268$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0710.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0710.json$t$, true),
  ($t$0711$t$, $t$Maplewood Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Use and Occupancy (CCU)$t$, $j$["Issued by: Township of Maplewood Building Department (Construction Official)","Contact: Darius Pokoj, Construction Official (signs the CCU instructions) · 973-762-8120 ext. 3700","Apply: Apply at least 10 business days before closing for the base fee; the Township allows 10 business days for the inspection unless expedited. Applications received after 4:00 pm count as the next business day.","How to apply: Download the Certificate of Continued Use and Occupancy form from the Township's CCU page, fill it out completely and submit it to the Maplewood Building Department, 574 Valley Street, Second Floor, at least 10 business days before closing. An inspector then contacts the applicant to set the inspection. Get the smoke/CO certificate from the Fire Department as well, since the CCU is not issued without it.","Valid for: 180 days from the date issued, and only for the buyer named on the application (a new buyer needs a new application)","Inspection of the premises by the Construction Official or his representative","All open permits must be closed","A smoke certificate (smoke/CO certificate from the Fire Department) must be issued first","Full payment of fees","Current and prospective owners must be listed as individuals (not an LLC or other entity); the new owner's driver's license number is required","Estate or trust sellers must show an original court document with a raised seal appointing the executor, trustee or power of attorney","The seller must personally sign a receipt for the certificate","If violations are found, the owner fixes them, or for sales only the buyer may submit a notarized letter accepting responsibility for the violations","Also: Open permits: All open permits must be closed before the CCU is issued.","Also: Smoke/CO certificate before CCU: The Building Department will not issue the CCU until the Fire Department's smoke certificate is issued."]$j$::jsonb, $j$[{"label":"CCU inspection, per unit, applied for at least 10 business days before closing","amount":"$150"},{"label":"Expedited, filed 6 to 9 business days before closing, per unit","amount":"$300"},{"label":"Expedited, filed 5 or fewer business days before closing, per unit","amount":"$500"},{"label":"Reinspection","amount":"$100"}]$j$::jsonb, $t$https://www.maplewoodnj.gov/home/showpublisheddocument/96/639256016314670000$t$, $t$https://www.maplewoodnj.gov/business/certificate-of-continued-use-occupancy$t$, $j$[{"url":"https://ecode360.com/9420421","label":"Official source (ecode360.com)"},{"url":"https://www.maplewoodnj.gov/home/showpublisheddocument/96/639256016314670000","label":"Official source (maplewoodnj.gov)"},{"url":"https://www.maplewoodnj.gov/home/showpublisheddocument/2694/639238604361170000","label":"Official source (maplewoodnj.gov)"},{"url":"https://www.maplewoodnj.gov/business/certificate-of-continued-use-occupancy","label":"Official source (maplewoodnj.gov)"}]$j$::jsonb, $t$Each time there is a transfer of ownership of property, or in the case of a rental property a change in tenancy, within the Township of Maplewood, a seller or lessor of such property must obtain from the Construction Official of the Township of Maplewood prior to the transfer of ownership or change of tenancy a certificate of continued use and occupancy$t$, $t$01ef1f64b5b2f1e4318fa5d508fb3f98e1c0b48b2058f1ffe68322dbb6cddf87$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":0,"fee_bad":0,"fee_unchecked":8,"quotes":13,"q_ok":1,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0711.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0711.json$t$, true),
  ($t$0711$t$, $t$Maplewood Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Maplewood Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Steve Zatko Jr., Fire Official · 973-762-6501 · szatko@maplewoodnj.gov","Apply: Fee depends on how many days before the inspection date it is scheduled: at least 10 days ahead for the lowest fee. Cancel at least 24 hours ahead to avoid charges.","How to apply: Schedule the inspection online with the Township's POS Fire Inspections form (GovPilot), linked from the Fire Department's 'Home Inspection at Time of Sale' page. Pay the fire inspector at the site on the inspection date by cash, check or money order payable to the 'Township of Maplewood'; online payments are not accepted.","Fire official in the NJ state directory, updated 1/12/2026: Steve Zatko · (973) 762-6500 · szatko@maplewoodnj.gov","Smoke alarms and carbon monoxide alarms inspected by the Maplewood Fire Department before the home is sold, leased or reoccupied","Portable fire extinguishers are no longer required in Maplewood for this certificate","Payment to the fire inspector at the inspection (cash, check or money order only)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, scheduled at least 10 days before the inspection date","amount":"$100"},{"label":"Scheduled 4 to 9 days before the inspection date","amount":"$125"},{"label":"Scheduled less than 4 days before the inspection date","amount":"$175"},{"label":"Recheck inspection","amount":"$100"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/70ceaeaa-30c_POS-Fire-Inspections-Township-of-Maplewood?uid=7127&ust=NJ&pu=1&id=0$t$, $t$https://www.maplewoodnj.gov/government/public-safety/fire-department/home-inspection-at-time-of-sale$t$, $j$[{"url":"https://www.maplewoodnj.gov/government/public-safety/fire-department/home-inspection-at-time-of-sale","label":"Official source (maplewoodnj.gov)"},{"url":"https://ecode360.com/9419747","label":"Official source (ecode360.com)"},{"url":"https://www.maplewoodnj.gov/government/public-safety/fire-department/bureau-of-training-and-fire-safety","label":"Official source (maplewoodnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Smoke Detector, Carbon Monoxide Alarm Compliance (CSDCMAC) is required before any "Use Group R-3 or R-4" dwelling unit is sold, leased or otherwise made subject to change of occupancy for residential purposes.$t$, $t$5ffab85f9d0bf1a258d8697d73536baeb1df25cde8f05e3a05320866c461021a$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":0,"fee_bad":0,"fee_unchecked":8,"quotes":13,"q_ok":1,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0711.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0711.json$t$, true),
  ($t$0712$t$, $t$Millburn Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Millburn Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Frank Catanese, Construction and Building Sub-Code Official · 973-564-7055","How to apply: No Township Certificate of Occupancy is needed to sell a home. The seller needs the smoke detector certification from the Millburn Fire Department (see fire certificate). The Township recommends calling the Building Department at 973-564-7055 well before closing to check for open permits.","Also: Open permits check: The Township recommends calling the Building Department (973-564-7055) well ahead of closing to find out about open permits, which could slow the sale. Permit records are also on the SDL Portal. Failing to get final inspections can bring a $2,000 penalty.","Also: House numbering: The fire inspection checks the house numbering ordinance: numbers at least 4 inches high, contrasting, fixed to the house and visible from the street."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://twp.millburn.nj.us/150/Building$t$, $j$[{"url":"https://twp.millburn.nj.us/Faq.aspx?QID=341","label":"Official source (twp.millburn.nj.us)"},{"url":"https://twp.millburn.nj.us/150/Building","label":"Official source (twp.millburn.nj.us)"}]$j$::jsonb, $t$Is a C.O (Certificate of Occupancy) required for sale of my home?$t$, $t$8e00761586d6790225f2a3470b5c6b7ff3dc4f54ade1e47aca71a0ced92d50d8$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":5,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0712.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0712.json$t$, true),
  ($t$0712$t$, $t$Millburn Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Millburn Fire Department, Fire Prevention Division (town fire bureau)","Contact: 973-564-7043 · ngerner@millburntwp.org","Apply: Fee depends on business days before closing: 10 or more for the lowest fee. Appointments based on inspector availability. Certificates are valid for 6 months from date of issue.","How to apply: Call 973-564-7043 to schedule (email ngerner@millburntwp.org). Pay before the inspection is completed, preferably online through the Township system (by calling the office or through the SDL Portal when scheduling), or by check payable to Township of Millburn delivered to Fire Headquarters, 459 Essex St, Administration Office (rear of building). Payments are not accepted in the field. A late or no-show owner or agent is charged a reinspection fee.","Fire official in the NJ state directory, updated 1/16/2026: Fire Official · (973) 564-7041","10-year sealed battery smoke alarm on every level, or hardwired as required; basement alarm at the bottom of the stairwell on the ceiling","Smoke alarms within 10 feet of all bedroom doors and a smoke alarm in every bedroom on the ceiling","Hardwired smoke alarms cannot be replaced with battery alarms; existing hardwired or monitored systems kept to original level","Smoke and CO alarms less than 10 years old, UL listed and working","Carbon monoxide alarms in hallways within 10 feet of all bedrooms and sleeping areas; plug-in, battery or hardwired accepted (not in switched outlets)","Secondary power source label 'CAUTION: Multiple Power Sources' by the electrical panel and meter if the home has solar, a generator, battery storage or other secondary power; label may not be handwritten (ANSI Z535.4)","House numbers at least 4 inches high, contrasting color, permanently fixed to the house and visible from the street (light post or mailbox numbers not accepted)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of inspection, request received 10 or more business days before closing","amount":"$100.00"},{"label":"Request received 4 to 10 business days before closing","amount":"$125.00"},{"label":"Request received fewer than 4 business days before closing","amount":"$175.00"},{"label":"Reinspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/essex/millburntwp$t$, $t$https://twp.millburn.nj.us/258/Fire-Prevention-Forms$t$, $j$[{"url":"https://twp.millburn.nj.us/DocumentCenter/View/17841/CO-inspection-Info-2026","label":"Official source (twp.millburn.nj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$MILLBURN FIRE PREVENTION DIVISION RESIDENTIAL REQUIREMENTS FOR SALE OR LEASE OF 1 & 2 FAMILY DWELLINGS CSACMAPFEC 5:70-2.3 (a)$t$, $t$a75fd436770fc4cf6280e019e0b534be01af2df41ab559668c375416808331b3$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":5,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0712.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0712.json$t$, true),
  ($t$0713$t$, $t$Montclair Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Montclair Township. Confirm with the office if the buyer's lender or title company asks.","Contact: 973-509-4951","How to apply: No Township resale Certificate of Occupancy. Montclair does not require a new C.O. for a sale, mortgage or refinance, but all current construction permits and open violations must be closed out before closing (call the Building Department at 973-509-4951 after getting the permit history by OPRA request). The smoke/CO certificate is still required (see fire certificate).","Also: Open permits and violations: All current construction permits and any open violations must be closed out before closing. Get the permit history by OPRA request, then call the Building Department at 973-509-4951."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.montclairnjusa.org/Government/Departments/Building-Office$t$, $j$[{"url":"https://www.montclairnjusa.org/Government/Departments/Building-Office","label":"Official source (montclairnjusa.org)"}]$j$::jsonb, $t$The Township of Montclair does not require the issuance of a new C.O. as a condition for the sale, mortgage, or refinancing of any property.$t$, $t$c6d7105b6ba7a568a7b30f13339ebe93f0a23592da494b81fa74402e49f2712a$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":8,"q_ok":0,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0713.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0713.json$t$, true),
  ($t$0713$t$, $t$Montclair Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Montclair Fire Department, Fire Prevention Bureau (Township of Montclair LEA) (town fire bureau)","Contact: Justin Thompson, Fire Official (NJ DCA fire directory) · 973-509-4769 · fireprevention@montclairnjusa.org","Apply: Submit all documents at least 10 days before closing. After emailing the application, call the office to make an appointment. The certificate expires 6 months after the inspection and is non-transferable.","How to apply: Read the Requirements for Certificate of Compliance, fill out the Application for Dwelling Smoke Detector & Carbon Monoxide Certification, and email all documents as PDFs (no pictures) to fireprevention@montclairnjusa.org at least 10 days before closing, then call to book the inspection. Pay by exact cash, check or money order to \"Township of Montclair, LEA\" at the final inspection; fees are non-refundable.","Fire official in the NJ state directory, updated 9/5/2025: Justin Thompson · (973) 509-4760 · jthompson@montclairnjusa.org","Smoke alarms on the ceiling at the bottom of each stair level, centrally located no more than 10 feet from outside each bedroom door, and in an open finished attic; a two-family with a common stairwell needs extra alarms at the highest level","Hardwired (A/C) smoke alarms from original construction or rehab cannot be replaced with battery-only alarms; a certified letter or report from a licensed electrician or licensed alarm technician that they were tested and work must come with the application","Battery-only smoke alarms must be 10-year sealed battery units listed to ANSI/UL 217","CO alarms (battery, hard-wired or plug-in, UL 2034, not past expiration) centrally located no more than 10 feet from outside each bedroom door, in all units except buildings with no fuel-burning device and no attached garage","Access to all units, the basement, attic and common areas","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke alarm and carbon monoxide alarm compliance (due at the inspection the home passes)","amount":"$75.00"}]$j$::jsonb, $t$https://www.montclairnjusa.org/files/sharedassets/public/v/1/government/departments/fire-department/fire-prevention/application-for-dwelling-smoke-detector-revised_fillable.pdf$t$, $t$https://www.montclairnjusa.org/Government/Departments/Fire-Department/Inspections$t$, $j$[{"url":"https://www.montclairnjusa.org/Government/Departments/Fire-Department/Inspections","label":"Official source (montclairnjusa.org)"},{"url":"https://www.montclairnjusa.org/files/sharedassets/public/v/1/government/departments/fire-department/fire-prevention/application-for-dwelling-smoke-detector-revised_fillable.pdf","label":"Official source (montclairnjusa.org)"},{"url":"https://www.montclairnjusa.org/files/sharedassets/public/v/1/residents/documents/requirements-for-certificate-of-smoke-compliance.pdf","label":"Official source (montclairnjusa.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Submit all documents at least 10 days before closing to be reviewed for approval$t$, $t$69d80cdae18c7dbe33985e03624379f4f03fde807b5106332a8763649c854b22$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":8,"q_ok":0,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0713.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0713.json$t$, true),
  ($t$0714$t$, $t$Newark City$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Code Compliance (CCC, also called Certificate of Continued Compliance)$t$, $j$["Issued by: City of Newark Code Enforcement Division (Department of Engineering, Division of Enforcement and Inspections), with a Zoning review","Contact: 973-733-3706","How to apply: Create an account on the City's one-stop portal (newarkportal.us), submit the Certificate of Code Compliance application and pay the fees; the Fire inspection can be requested and paid on the same portal (the portal adds a service fee). Review the fire checklist and close any open permits before the inspection. Certificates are released only to the seller or the seller's agent.","Valid for: 90 days from the date of issuance","Inspection for compliance with City ordinance plus a zoning review","Separate Fire Department fire safety (smoke/CO) inspection and certificate","No open building or construction permits","Only the property owner or the owner's agent can request it (buyer only for auction or sheriff sale purchases)","If violations remain, the buyer may take responsibility by notarized affidavit with the signed contract, violations report and buyer ID (corrections after closing)","Also: Open permits: Make sure there are no open building or construction permits before the CCC inspection.","Also: Zoning review: A zoning review is part of the Certificate of Code Compliance (Zoning 973-733-3714).","Also: Buyer affidavit for violations: If violations remain, the buyer can accept responsibility with a notarized affidavit, signed contract, violations report copy and buyer ID (plus LLC/corporate formation papers if applicable)."]$j$::jsonb, $j$[{"label":"Certificate of Code Compliance, 1-2 dwelling units","amount":"$400"},{"label":"Fire certificate (smoke/CO), 1-2 dwelling units","amount":"$35"}]$j$::jsonb, $t$https://newarkportal.us/Home/CCC$t$, $t$https://newarkportal.us/Home/CCC$t$, $j$[{"url":"https://newarkportal.us/Home/CCC","label":"Official source (newarkportal.us)"},{"url":"https://ecode360.com/36690942","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$As per City Ordinance prior to the transfer of ownership of a residential or mixed used property a code compliance certificate and a fire department certificate of must be obtained.$t$, $t$7865b733e1ef06bde15cad74ff8f9c40f46debd4d7ad8e9aaf1b663429e78671$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0714.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0714.json$t$, true),
  ($t$0714$t$, $t$Newark City$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Newark Fire Department, Fire Prevention (town fire bureau)","Contact: Gwendolyn Saleem, Fire Official · 973-733-7495 · saleemg@ci.newark.nj.us","Apply: Fire certificate expires six months after issuance. No rush tiers published on the portal.","How to apply: Request and pay for the Fire inspection on the City's one-stop CCC portal (newarkportal.us) together with the Certificate of Code Compliance, or contact Fire at 973-733-7495.","Fire official in the NJ state directory, updated 10/7/2025: Gwendolyn Saleem · (973) 733-7495 · saleemg@ci.newark.nj.us","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-2.3 (the City's fire checklist was not found online)","Fire safety inspection by the Newark Fire Department is part of the transfer process alongside the CCC","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire certificate (smoke/CO), 1-2 dwelling units","amount":"$35"}]$j$::jsonb, $t$https://newarkportal.us/Home/CCC$t$, $t$https://newarkportal.us/Home/CCC$t$, $j$[{"url":"https://newarkportal.us/Home/CCC","label":"Official source (newarkportal.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$you will be able to request and pay for the Fire Inspection as well.$t$, $t$c37b8c674af64d739f1830e3c1893314f78c1bab827efdec90584c299df0c0ef$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0714.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0714.json$t$, true),
  ($t$0716$t$, $t$Nutley Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (Zoning Certificate)$t$, $j$["Issued by: Township of Nutley Code Enforcement Department","Contact: (973) 284-4957","Apply: Inspection requests must be in writing (SDL Portal or request form) at least 24 hours in advance. Transfer of real estate inspections: Building/Zoning Monday to Friday 8:00am to 3:30pm; Fire/Zoning Monday, Wednesday and Thursday 11:00am to 3:00pm.","How to apply: Apply to the Code Enforcement Department, 2nd floor of the Municipal Building, 1 Kennedy Drive (office hours Monday to Friday 8:00 a.m. to 4:00 p.m., closed 12:30 to 1:30). Since July 1, 2026 inspection requests must be in writing through the SDL Portal (Nutley) or the Township's inspection request form, at least 24 hours ahead. The smoke/CO certificate is a separate application to Nutley Fire Prevention.","Safety inspection by Code Enforcement before the sale, conveyance or rental (not a home inspection)","No work done without permits; all open building permits closed through final inspections before the Zoning Certificate is issued","Working smoke detectors on each level, including basement and walk-up attic, and within 10 feet of each bedroom","Carbon monoxide detector in the common area outside bedrooms, within 10 feet of each bedroom, where there is a fuel burning appliance or attached garage","Relief valves on the water heater and boiler piped to within 6 inches of the floor","Sump pump (if present) discharging outside, not into the sanitary sewer or onto adjoining property","Handrails/guardrails for anything over four steps; stairs in good shape inside and out","Switch and outlet covers in place; electric panel with no openings; no exposed wires or open boxes","Attached garage with no holes in walls or ceilings; toilets and faucets working; hot water at least 110 degrees with hot on the left","Proper fit and venting of furnace/boiler and water heater to the chimney; metal or UL listed foil dryer vents; bathroom ventilation (window or mechanical vent)","No broken windows or glass, no illegal conversions or living areas, no other visible safety faults","House numbers 4 to 8 inches high, visible from the street","Compliance with zoning regulations for the area","Also: Final water reading: Contact the Water Department at (973) 284-4962, schedule online, or email waterbilling@nutleynj.org at least 24 hours in advance to schedule a final water reading.","Also: Open building permits: All open building permits must be closed by scheduling final inspections before the Zoning Certificate is issued.","Also: Sump pump discharge: A sump pump must discharge outside the structure, not into the sanitary sewer or onto adjoining property; checked at the CO inspection."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy filing fee, per dwelling unit up to a 3 family (stated in the 2018 rental change-of-occupancy notice; confirm it applies to sales)","amount":"$75"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/essex/nutley$t$, $t$https://www.nutleynj.org/code-enforcement$t$, $j$[{"url":"https://www.nutleynj.org/media/Forms-Permits-Applications/Code%20Enforcement%20/CO_Requirements.pdf","label":"Official source (nutleynj.org)"},{"url":"https://www.nutleynj.org/code-enforcement","label":"Official source (nutleynj.org)"},{"url":"https://www.nutleynj.org/media/Forms-Permits-Applications/Code%20Enforcement%20/Information%20Updates/Important%20Update%20for%20Homeowners%20-%20Use%20and%20Occupancy%20-%20Web.pdf","label":"Official source (nutleynj.org)"}]$j$::jsonb, $t$A Continued Certificate of Occupancy or “Zoning Certificate” is required on all resales, rentals, and/or changes or tenancy.$t$, $t$7a4750b1c34b57b9f5f274aa38f657618a591c7c1744c27ed267f46e82d7348b$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0716.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0716.json$t$, true),
  ($t$0716$t$, $t$Nutley Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Nutley Fire Department, Fire Prevention Bureau (Department of Public Safety) (town fire bureau)","Contact: Paul Cafone, Chief · (973) 284-4937 · pcafone@nutleynj.org","Apply: Fee depends on how many business days before the inspection date the application is received: more than 10 business days for the lowest fee.","How to apply: Fill out the Residential Certificate of Smoke Detector and Carbon Monoxide Compliance Application (owner/seller and agent details, block and lot, sale or rental) and submit it with the fee payable to the Nutley Fire Department, 228 Chestnut Street. Read all four pages; the inspection must pass before the certificate is issued.","Fire official in the NJ state directory, updated 5/22/2026: Paul Cafone · (973) 284-4937 · pcafone@nutleynj.org","UL approved smoke detectors on every level (excluding crawl spaces and unfinished attics with pull-down stairs), on the ceiling and within 10 feet of every bedroom, or within 10 feet of the stairway on levels without bedrooms","All battery smoke detectors must be 10-year sealed battery type; all existing hardwired systems must be maintained","Carbon monoxide alarms (UL 2034, dated) within 10 feet of all sleeping areas, with more on each floor that has sleeping areas","Homes with secondary power sources need a printed label (such as CAUTION: MULTIPLE SOURCES OF POWER) within 18 inches of the main electrical panel and electric meter (P.L.2025, c.19)","Homes with a monitored central station fire alarm must have it tested beforehand by a Division of Fire Safety certified company and give the test record to the inspector","Incomplete items at inspection mean automatic failure and a re-inspection; no specific inspection times are given","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and CO certificate, application received more than 10 business days before inspection","amount":"$45"},{"label":"Application received 4 to 10 business days before inspection","amount":"$90"},{"label":"Application received fewer than 4 business days before inspection","amount":"$161"}]$j$::jsonb, $t$https://www.nutleynj.org/media/Forms-Permits-Applications/Fire%20Department%20/Residential%20Smoke%20Detector%20and%20Carbon%20Monoxide%20Application.pdf$t$, null, $j$[{"url":"https://www.nutleynj.org/media/Forms-Permits-Applications/Fire%20Department%20/Residential%20Smoke%20Detector%20and%20Carbon%20Monoxide%20Application.pdf","label":"Official source (nutleynj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$before any residential dwelling is leased, sold, or subject to change in occupancy for residential purposes, the owner shall obtain a certificate of compliance from Nutley Fire Prevention.$t$, $t$3138699ed659f746b5784c5209112fb93f97dfbdc4fcf74ade47d19096a3b2c8$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0716.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0716.json$t$, true),
  ($t$0717$t$, $t$City of Orange Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (Certificate for Sales or Transfer of Title)$t$, $j$["Issued by: City of Orange Township Code Enforcement Division","Contact: Khalfani Alleyne, Chief Code Enforcement Inspector/Zoning Officer (Code Enforcement Assistant: Linda Drummond, ldrummond@orangenj.gov… · (973) 952-6066 · kalleyne@orangenj.gov","How to apply: Fill out the City's Certificate for Sales or Transfer of Title form, attach a copy of the contract signed by both seller and purchaser, and return it to the Code Enforcement Division, Room 305, City Hall, 29 North Day Street, Orange. The form asks for a certified check or money order payable to City of Orange Township. The fire certificate (smoke/CO) is a separate application to the Fire Prevention Bureau.","Inspection by the Code Enforcement Division before the sale or transfer of title","Copy of the sales agreement attached to the application, signed by both seller and purchaser","No work done without permits","Working smoke detector on each level, including basement","Carbon monoxide detector, one per unit, usually in the sleeping area or level","Relief valves on the hot water heater and boiler piped to within 8 inches of the floor","Sump pump (if present) piped to the outside, not connected to the sanitary sewer","Handrails for anything over two steps; stairs in good shape inside and out","All switch and outlet covers in place; electric panel in good shape; no exposed wires or open electrical boxes","Attached garage with no holes in walls or ceilings","All toilets and faucets working; hot water at least 110 degrees with hot faucet on the left","Proper fit and venting of furnace/boiler and water heater to the chimney","No broken windows or glass, and no other visible safety faults","Also: Open permits / work without permits: Work done without permits is one of the items checked at the Certificate of Habitability inspection.","Also: Sump pump discharge: A sump pump, if present, must be piped to the outside and not connected to the sanitary sewer line; checked at the Certificate of Habitability inspection."]$j$::jsonb, $j$[{"label":"Certificate of Habitability, one unit, initial inspection (first reinspection no fee)","amount":"$200"},{"label":"Certificate of Habitability, one unit, second reinspection","amount":"$100"},{"label":"Certificate of Habitability, two units, initial inspection (first reinspection no fee)","amount":"$300"},{"label":"Certificate of Habitability, two units, second reinspection","amount":"$200"}]$j$::jsonb, $t$https://www.orangenj.gov/DocumentCenter/View/162/Certificate-for-Sales-or-Transfer-of-Title-PDF$t$, $t$https://www.orangenj.gov/176/Code-Enforcement-Division$t$, $j$[{"url":"https://www.orangenj.gov/176/Code-Enforcement-Division","label":"Official source (orangenj.gov)"},{"url":"https://www.orangenj.gov/DocumentCenter/View/162/Certificate-for-Sales-or-Transfer-of-Title-PDF","label":"Official source (orangenj.gov)"},{"url":"https://ecode360.com/34548261","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Certificate of Habitability Fees for Residential Property Sales$t$, $t$e91b108e9f199a7a7910fee8e6287cfaca111ef42f352138a7500fbf0f168efa$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0717.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0717.json$t$, true),
  ($t$0717$t$, $t$City of Orange Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Orange Township Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Sharif Jennings, Fire Official (Office Administrator: Tonia Whidbee, 973-346-2300 ext 6130) · (973) 952-6129 · sjennings@orangenj.gov","Apply: Fee depends on how many business days before the inspection the request is received: more than 10 business days for the lowest fee. An inspection date is given only once all required documents are received.","How to apply: Download the Fire Certification Application, fill in all owner, buyer, address and appointment details, attach the sales contract (and LLC papers or an attorney letter if they apply), and pay by certified check or money order payable to City of Orange, or online through the City's online bill pay (Fire Department) and attach the receipt. Call (973) 952-6129 or (973) 952-6130 for appointments. The office is at 419 Central Avenue, 2nd floor. A no-show is charged the full inspection cost; fees are non refundable and certificates are non-transferable.","Fire official in the NJ state directory, updated 7/15/2026: Sharif Jennings · (973) 266-4234 · sjennings@orangenj.gov","Smoke detector on each level, including the basement and attic (the placement sheet says no detector is needed if the attic is not finished), and outside each separate sleeping area, on or near the ceiling","Ten-year sealed battery single station smoke detectors listed to UL 217; proof of purchase (box or receipt) required the day of inspection","Carbon monoxide detectors on each floor used for sleeping, outside bedrooms within 10 feet of bedroom doors","Existing hardwired systems installed under a building permit must be kept at the same level; battery detectors are not acceptable replacements","No double sided tape for mounting equipment","ABC fire extinguisher, minimum 2A:10B:C, no more than 10 lb, mounted on the wall within 10 feet of the kitchen in an open, easily accessible spot (form still lists it)","Copy of the sales contract; LLC buyers or sellers must provide a certificate of registration or organization","If the property is vacant or needs rehabilitation, a letter from the attorney to the Fire Official (template enclosed in the packet)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector certificate, 1 and 2 family/condo, request received more than 10 business days prior","amount":"$100.00"},{"label":"Request received four to ten business days prior","amount":"$125.00"},{"label":"Request received fewer than four business days prior","amount":"$175.00"},{"label":"Reinspection fee","amount":"$50.00"}]$j$::jsonb, $t$https://www.orangenj.gov/DocumentCenter/View/5570/Fire-Certification-Application$t$, $t$https://www.orangenj.gov/241/Fire-Prevention$t$, $j$[{"url":"https://www.orangenj.gov/DocumentCenter/View/5570/Fire-Certification-Application","label":"Official source (orangenj.gov)"},{"url":"https://www.orangenj.gov/241/Fire-Prevention","label":"Official source (orangenj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Attach a copy of the sales contract with application$t$, $t$eeb99b5cd05bd3bebc875eefec83b8ca851d30fb5c6a12fb46c6ee0f783c037a$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0717.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0717.json$t$, true),
  ($t$0718$t$, $t$Roseland Borough$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate$t$, $j$["Issued by: Borough of Roseland Code Enforcement Department (Code Enforcement Officer)","Contact: 973-403-6046 · codeenforcement@roselandnj.org","How to apply: Complete the Residential Resale Application (Borough website, Forms & Applications) and submit it with the $200 fee to the Code Enforcement Department, 300 Eagle Rock Avenue, Roseland (cash or check). Check the box for a resale certificate, or for a temporary resale certificate, which needs a letter of request from the buyer's attorney. Schedule the final water meter reading separately.","Valid for: 180 days","Inspection by Code Enforcement, with review for UCC, housing and zoning compliance","Working smoke detector on each level including the basement; 10-year sealed battery units allowed but may not replace required hardwired detectors","Carbon monoxide detector in the vicinity of all sleeping rooms","Explosive natural gas alarm installed per the manufacturer's specifications","Smoke, CO and explosive gas detectors no older than 10 years","No loose or missing stair treads, risers, handrails or guardrails","No loose or missing electrical panel covers, switch/receptacle plates or junction box covers","Sump pump (if any) piped outside, not into the sanitary sewer","Proper fit and venting of furnace/boiler and water heater to the chimney; water heater relief valve discharging 2 to 6 inches above the floor","No unsealed penetrations, holes or missing sheetrock or plaster in attached garage walls or ceilings","Seller must close all permits before the sale","Final water meter reading must be scheduled and completed before the certificate is released","Buyer's name and phone number must be given","Also: Final water meter reading: The seller or seller's attorney must schedule the final water meter reading with the Borough Water Department before closing; the certificate is not released until it is done. A $150.00 final water meter read fee is added to the final water bill.","Also: Open permits: The seller must close all permits before selling.","Also: Zoning compliance: The resale certificate is issued only if the use complies with zoning or is a valid preexisting nonconforming use."]$j$::jsonb, $j$[{"label":"Residential resale certificate, per dwelling unit","amount":"$200"},{"label":"Residential resale application fee (as printed on the application)","amount":"$200"}]$j$::jsonb, $t$https://www.roselandnj.org/361/Residential-Resale-Application-PDF$t$, $t$https://www.roselandnj.org/Directory.aspx$t$, $j$[{"url":"https://ecode360.com/34521931","label":"Official source (ecode360.com)"},{"url":"https://www.roselandnj.org/361/Residential-Resale-Application-PDF","label":"Official source (roselandnj.org)"},{"url":"https://www.roselandnj.org/Directory.aspx","label":"Official source (roselandnj.org)"}]$j$::jsonb, $t$No owner, agent, or any person or entity, shall rent, lease, sell, transfer ownership, or in any way deliver up for use, change of use, or occupancy any business, building, dwelling unit, lodging unit, rooming unit, or boarding unit, until a residential resale certificate, residential rental certificate, commercial rental certificate, or commercial resale certificate has been issued by the Code Enforcement Officer$t$, $t$0b2fc1cdbb227e11077cee18a86be5c0b6e651998d5181c373b34988cedd44a7$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":1,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0718.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0718.json$t$, true),
  ($t$0718$t$, $t$Roseland Borough$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Roseland Code Enforcement Department (smoke/CO inspection is part of the Residential Resale Certificate) (town fire bureau)","Contact: Allen Bell, Fire Prevention Official · 973-226-0512 · fireprevention@roselandnj.org","How to apply: There is no separate smoke/CO application on the Borough site. The smoke, CO and explosive gas alarm inspection is done as part of the Residential Resale Certificate inspection, applied for on the Residential Resale Application.","Fire official in the NJ state directory (town), updated 1/19/2023: Allen Bell, Jr · (973) 226-0512 · fireprevention@roselandnj.org","Smoke detector on each level, including the basement (10-year sealed battery units allowed; hardwired units may not be replaced with battery units)","Carbon monoxide detector in the vicinity of all sleeping rooms","Explosive natural gas alarm (Borough requirement)","Detectors no older than 10 years","A fire extinguisher is not required in one- and two-family homes (Borough code); the application's office checklist still has a fire extinguisher box","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.roselandnj.org/361/Residential-Resale-Application-PDF$t$, $t$https://www.roselandnj.org/Directory.aspx$t$, $j$[{"url":"https://ecode360.com/34521931","label":"Official source (ecode360.com)"},{"url":"https://www.roselandnj.org/Directory.aspx","label":"Official source (roselandnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A residential resale certificate, residential rental certificate, commercial rental certificate, and or a commercial resale certificate shall not be issued until an inspection and/or test of all smoke detection devices, carbon monoxide devices, and explosive gas alarms within the building or structure shall have been performed by the Code Enforcement Officer$t$, $t$d901b4dec642d6c7bcdbea508a852640dbd485d9781ab38c56479741d7213cf3$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":1,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0718.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0718.json$t$, true),
  ($t$0719$t$, $t$South Orange Village$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: South Orange Fire Prevention Bureau (Fire Official), within the Building and Code Enforcement Department","Contact: Anthony Grenci, Fire Official · 973-378-7715 x7703 · firebureau@southorange.org","Apply: Expedited fees apply when the request comes 10 business days or less before closing; apply at least 11 business days ahead to avoid them.","How to apply: Apply online with the Village's Certificate of Continued Occupancy Application (GovPilot), linked from the Fire Prevention Bureau page and the Permit & License Application Forms page, and pay online. The owner, realtor or other contact can apply. Expedited fees count business days between receiving the request and the closing date, not counting the day the application is submitted. Fees are not refunded if the submission is incorrect. Office: 76 South Orange Avenue, Suite 302, (973) 378-7715.","Inspection by the Fire Official or inspector for compliance with N.J.A.C. 5:70-4.19 (smoke alarms, carbon monoxide alarms); smoke detector inspection is part of the CCO","Owner certifies all structures have valid zoning and building permits, registrations and certificates; the CCO verifies there are no open permits or violations unless a separate written agreement is attached","The CCO does not confirm zoning compliance; that needs a zoning verification letter, zoning permit or Certificate of Legal Nonconformity","No rubbish, debris or bulk garbage left on the property before the new occupancy","Application asks for buyer details, proposed closing date, realtor, room counts, accessory structures, house number visibility and any secondary power source (solar, generator, battery storage)","Secondary power source warning label within 18 inches of the main electric panel and meter, not handwritten","Monitored or low-voltage alarm systems need a current full NFPA 72 report from an alarm contractor or certified electrician","Someone must be at the property to give the inspector access (missed appointment fee otherwise)","Also: Open permits and violations: The CCO verifies there are no open permits or violations; the owner certifies all structures have valid zoning and building permits.","Also: Zoning verification (optional): The CCO does not confirm zoning compliance. Zoning compliance can only be confirmed with a zoning verification letter or zoning permit from the Zoning Officer, or a Certificate of Legal Nonconformity from the Zoning Board."]$j$::jsonb, $j$[{"label":"CCO inspection, one-family","amount":"$150.00"},{"label":"CCO inspection, two-family","amount":"$200.00"},{"label":"CCO, single family or condo/townhouse (online application)","amount":"$150"},{"label":"CCO, two-family (online application)","amount":"$200"},{"label":"CCO first re-inspection","amount":"$50.00"},{"label":"CCO second re-inspection","amount":"$50.00"},{"label":"CCO third or later re-inspection","amount":"$75.00"},{"label":"Expedited fee, request 5 to 10 business days before closing (added to inspection fee)","amount":"$50"},{"label":"Expedited fee, request 4 or fewer business days before closing (added to inspection fee)","amount":"$100"},{"label":"Missed appointment fee","amount":"$50"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/b2d0482d-1a2_CCO-Application-southorangevillage?uid=6977&ust=NJ&pu=1&id=0$t$, $t$https://www.southorange.org/697/Fire-Prevention-Bureau-Inspections$t$, $j$[{"url":"https://www.southorange.org/697/Fire-Prevention-Bureau-Inspections","label":"Official source (southorange.org)"},{"url":"https://www.southorange.org/498/Code-Enforcement","label":"Official source (southorange.org)"},{"url":"https://s3-us-west-2.amazonaws.com/municipalcodeonline.com-new/southorange/ordinances/documents/1780929121_2026-10%20%5BADOPT%5D%20Ordinance%20Amendment%20to%20Village%20Code%20157%20re%20Fire%20Inspection%20Fees.pdf","label":"Official source (s3-us-west-2.amazonaws.com)"},{"url":"https://main.govpilot.com/web/public/b2d0482d-1a2_CCO-Application-southorangevillage?uid=6977&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"}]$j$::jsonb, $t$The issuance of CCO certificates for the change of ownership for both commercial and residential properties$t$, $t$aeb37fb1de4b251f91f5c60c5f4f131a408b001e6820159b005c52185e2f25d5$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":11,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":9,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0719.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0719.json$t$, true),
  ($t$0719$t$, $t$South Orange Village$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: South Orange Fire Prevention Bureau (town fire bureau)","Contact: Anthony Grenci, Fire Official · 973-378-7715 x7703 · firebureau@southorange.org","Apply: Smoke detector inspection is done as part of the CCO; request at least 11 business days before closing to avoid expedited fees.","How to apply: For a sale, the smoke and CO alarm inspection is part of the Certificate of Continued Occupancy: apply online with the CCO application (GovPilot). Questions: Fire Prevention Bureau, 76 South Orange Avenue, Suite 302, 973-378-7715, firebureau@southorange.org.","Fire official in the NJ state directory (town), updated 1/12/2026: Anthony Grenci · (973) 378-7715 · agrenci@southorange.org","Smoke alarms UL 217 listed, no more than 10 years old; standalone battery alarms must be 10-year sealed","Smoke alarms on each level and outside each sleeping area; hardwired, interconnected and in-bedroom alarms depending on the year the house was built","Hardwired alarms stay hardwired; basement alarm within 10 feet of the base of the stairs","Carbon monoxide alarm on each level, and on sleeping levels within 10 feet of bedroom doors; UL 2034; battery, plug-in or hardwired","Secondary power source label within 18 inches of the main electric panel and meter","Monitored or low-voltage fire alarm systems need a current full NFPA 72 report","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector compliance certificate fee (Village Code 157-12F)","amount":"$50.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/b2d0482d-1a2_CCO-Application-southorangevillage?uid=6977&ust=NJ&pu=1&id=0$t$, $t$https://www.southorange.org/697/Fire-Prevention-Bureau-Inspections$t$, $j$[{"url":"https://www.southorange.org/697/Fire-Prevention-Bureau-Inspections","label":"Official source (southorange.org)"},{"url":"https://s3-us-west-2.amazonaws.com/municipalcodeonline.com-new/southorange/ordinances/documents/1780929121_2026-10%20%5BADOPT%5D%20Ordinance%20Amendment%20to%20Village%20Code%20157%20re%20Fire%20Inspection%20Fees.pdf","label":"Official source (s3-us-west-2.amazonaws.com)"},{"url":"https://www.southorange.org/DocumentCenter/View/8891/Residential-Inspection-Requirements-PDF","label":"Official source (southorange.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Fire Prevention Bureau is also responsible to make sure that each time there is a change of occupancy in a residence the Seller or Landlord complies with the current laws on smoke detector and Carbon monoxide detector compliance.$t$, $t$7ffcaf3c8bd70da6edcc922b90ede3d1315580aba767f40837eafcd3f17a10e7$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":11,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":9,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0719.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0719.json$t$, true),
  ($t$0722$t$, $t$West Orange Township$t$, $t$ESSEX$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), residential$t$, $j$["Issued by: Township of West Orange Construction Official, with Zoning Official approval (Department of Planning & Development)","Contact: Geniece Gary-Adams, Director Planning & Development/Zoning Official · (973) 325-4119 · zoningofficial@westorange.org","How to apply: Fill out the Residential CCO application (typed or neatly printed; mark Sale, single or multi-family; owner, buyer, inspection contact and closing date) and submit it with a check or money order payable to 'Township of West Orange'. Fees are not refunded once processed. Zoning Enforcement, Property Maintenance & Housing, 66 Main Street Room 200, West Orange, NJ 07052.","Valid for: A temporary CCO may be issued for minor violations, with repairs due within 30 days or as set by the construction official; the permanent CCO then has no added fee","Inspection for compliance with Township and State health and safety codes, fire safety (Chapter 18, Section 3) and the Land Use Regulations","Closure of all open permits","Smoke and carbon monoxide detectors installed (battery smoke alarms must be 10-year sealed units)","Sidewalk and walkway condition, entrance steps with balusters and handrails, basement stairway","Electrical hazards, grounded receptacles, relief valves on boilers and water heaters, sump pump discharge, venting of heating equipment and bathrooms","General property maintenance and structural condition; unregistered and commercial vehicles removed","Zoning conformance for the use of the property; work possibly done without permits is noted","Electricity and water on for the inspection","CCO states the maximum number of occupants","Also: Open permits: All open permits must be closed for the CCO.","Also: Sidewalk and walkways: Condition of sidewalks and walkways is on the CCO checklist.","Also: Tax search notice: The Tax Assessor advises anyone requesting a tax assessment search that a CCO is required for the sale."]$j$::jsonb, $j$[{"label":"CCO, single unit residential dwelling","amount":"$200.00"},{"label":"CCO, two unit residential dwelling","amount":"$275.00"},{"label":"CCO reinspection","amount":"$75.00"},{"label":"Determination that a CCO is not required before a sale","amount":"$250.00"}]$j$::jsonb, $t$https://www.westorange.org/DocumentCenter/View/44$t$, $t$https://www.westorange.org/778/Zoning-Enforcement-Property-Maint-Public$t$, $j$[{"url":"https://www.westorange.org/DocumentCenter/View/44","label":"Official source (westorange.org)"},{"url":"https://www.westorange.org/778/Zoning-Enforcement-Property-Maint-Public","label":"Official source (westorange.org)"}]$j$::jsonb, $t$Prior to the sale or rental of any existing residential structure containing one (1) unit or more, a Certificate of Continued Occupancy must be obtained which shall be issued by the Construction Official or designated agency or department provided with the authority to grant and issue such certificates.$t$, $t$ed1f82186fc6cf2dec059ae273ade8bfeb88391f69aaf301690c3be19e1e0d70$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":3,"q_bad":0,"q_unchecked":13},"source":"property/data/municipal-requirements/checked/0722.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0722.json$t$, true),
  ($t$0722$t$, $t$West Orange Township$t$, $t$ESSEX$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: West Orange Building Department (smoke and CO detectors checked as part of the CCO); fire code LEA: West Orange Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Joseph Matullo, Fire Official (FireOfficial@westorange.org, 973-325-4175); Construction Official is Tom Biondi, Jr. · (973) 325-4112 · wobuilding@westorange.org","How to apply: The smoke and carbon monoxide detector check is part of the Residential CCO inspection (see resale certificate). No separate smoke certificate application or fee was found on the Fire Department pages; confirm whether the Fire Prevention Bureau issues a separate certificate.","Fire official in the NJ state directory, updated 2/9/2026: Joseph Matullo · (973) 325-4175 · FireOfficial@westorange.org","Battery smoke detectors and combination units in 1-2 family homes must be 10-year sealed battery alarms, with the manufacture date written on the outside","Hardwired smoke detector systems may not be downgraded to battery systems","Carbon monoxide detector in or outside the bedroom area, no more than 10 feet from any bedroom; battery or plug-in units are acceptable","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.westorange.org/DocumentCenter/View/44$t$, $t$https://www.westorange.org/777/Building-Construction-Code-Enforcement$t$, $j$[{"url":"https://www.westorange.org/DocumentCenter/View/44","label":"Official source (westorange.org)"},{"url":"https://www.westorange.org/120/Prevention","label":"Official source (westorange.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke & Carbon Monoxide Detectors Installed$t$, $t$c157858cf1caf51d7ce2781e7b9dbdc0c36a6e3f5c96b81d3246583cc42c6ef1$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":16,"q_ok":3,"q_bad":0,"q_unchecked":13},"source":"property/data/municipal-requirements/checked/0722.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/0722.json$t$, true),
  ($t$1802$t$, $t$Bernards Township$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance (CRC)$t$, $j$["Issued by: Bernards Township Code Enforcement Division (Construction Code office)","Contact: Dennis Bettler, Construction Official · 908-204-3173","Apply: Owner or agent must apply at least 10 business days before the change of ownership; the fee rises inside 10 and 4 calendar days of closing.","How to apply: Use the Construction Records Clearance Application in the Township's 'Selling or Renting Your Home' packet, or apply online, and mail or bring it with payment (cash or check) to Bernards Township Code Enforcement, 277 S. Maple Ave., Basking Ridge, NJ 07920, ATTN: CRC Certificate. The certificate is emailed to the owner or agent.","Records check (not a physical inspection) that there are no open construction or zoning permits","If permits are open, all final inspections and approvals must be done and certificates issued before the CRC","Application lists the closing date (required), home type, approximate year built, and whether there is a pool, pool fence, finished basement or second kitchen, and whether the address is displayed on the building","Exempt if there is no change in physical occupancy for deed corrections, transfers between spouses, estate distributions, refinancing and similar transfers; rentals are exempt","Also: Open construction and zoning permits: All open construction or zoning permits must be finaled before the Construction Records Clearance is issued."]$j$::jsonb, $j$[{"label":"CRC, request more than 10 calendar days before closing","amount":"$40"},{"label":"CRC, request within 10 calendar days of closing","amount":"$75"},{"label":"CRC, request within 4 calendar days of closing","amount":"$125"}]$j$::jsonb, $t$https://www.bernards.org/government/forms/construction/documents-1/1149-selling-your-home-pdf/file$t$, $t$https://www.bernards.org/departments/construction$t$, $j$[{"url":"https://ecode360.com/11919082","label":"Official source (ecode360.com)"},{"url":"https://www.bernards.org/departments/construction","label":"Official source (bernards.org)"},{"url":"https://www.bernards.org/government/forms/construction/documents-1/1149-selling-your-home-pdf/file","label":"Official source (bernards.org)"}]$j$::jsonb, $t$A CRC shall be required prior to the sale of any residential structure within the Township.$t$, $t$f2773a6c085abce9050d568207171fe316253fe26e3a8c00746dd4b8a0e784c9$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1802.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1802.json$t$, true),
  ($t$1802$t$, $t$Bernards Township$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Bernards Township Fire Prevention Bureau (town fire bureau)","Contact: Richard Von den Steinen, Fire Official · 908-204-2511 · rvondensteinen@bernards.org","Apply: Fee depends on how close to the change of occupancy the inspection is requested: more than 10 days for the lowest fee. Pay within 24 hours of booking if paying in person or the time slot is not held.","How to apply: Create a free SDL Portal account and fill out the Township's smoke detector certification form online (link in the 'Selling or Renting Your Home' packet), choose an inspection date and time, and pay online (surcharge) or in person at 277 South Maple Avenue within 24 hours. Questions: 908-204-2511.","Fire official in the NJ state directory (town), updated 1/14/2026: Richard Von Den Steine · (908) 204-2511 · rvondensteinen@bernards.org","Smoke alarms located per N.J.A.C. 5:70-4.19 and maintained per NFPA 72","Carbon monoxide alarms located per N.J.A.C. 5:70-4.19 and maintained per NFPA 720","Portable fire extinguisher installed per N.J.A.C. 5:70-4.19(e) (Township code and Bureau page still list it)","Homes with an installed fire alarm system may need to show testing and maintenance records","New owners or tenants may not move in before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, CO alarm and extinguisher certificate, standard","amount":"$50"},{"label":"Requested within 10 days of the change of occupancy","amount":"$100"},{"label":"Requested within 4 days of the change of occupancy","amount":"$150"}]$j$::jsonb, $t$https://www.sdlportal.com/towns/nj/somerset/bernardstwp/forms/7471cf56-d2e1-4ce7-9e5b-d489858433cf?wf=1$t$, $t$https://www.bernards.org/departments/fire-prevention$t$, $j$[{"url":"https://www.bernards.org/departments/fire-prevention","label":"Official source (bernards.org)"},{"url":"https://ecode360.com/11919166","label":"Official source (ecode360.com)"},{"url":"https://www.bernards.org/government/forms/construction/documents-1/1149-selling-your-home-pdf/file","label":"Official source (bernards.org)"},{"url":"https://www.bernards.org/government/documents/forms-documents/department-documents/fire-prevention/fire-prevention-forms/fire-prevention-documents/4719-selling-or-renting-a-home-in-bernards-twp-2025-guidelines/file","label":"Official source (bernards.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/11919168","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$If you are planning to sell, rent/lease or otherwise change occupancy of your home, you are required to obtain a Certificate of Smoke Alarm, Carbon Monoxide and Portable Fire Extinguisher Compliance from the Bernards Township Fire Prevention Bureau.$t$, $t$49e50baf2a553ff47b1b91fbeee7d388e6c8985e3badc44bb0226bb0a50a2cf6$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1802.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1802.json$t$, true),
  ($t$1804$t$, $t$Bound Brook Borough$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Smoke Alarm Carbon Monoxide Fire Extinguisher Housing Compliance$t$, $j$["Issued by: Borough of Bound Brook Bureau of Fire Prevention (Fire Official / Fire Marshal)","Contact: Erik J Mickelsen, Fire Official (NJ DCA fire directory) · (732) 356-0833 · emickelson@boundbrook-nj.org","Apply: Fee must be paid before the inspection is scheduled; the certificate is issued within six business days of the inspection if the property complies","How to apply: Fill out the Application for CSACMFEHC (seller completes page 2 for every unit), pay $125 per unit before the inspection is scheduled, and submit to the Bureau of Fire Prevention. The office emails the certificate after the home passes. Fire Prevention, 230 Hamilton Street, Bound Brook, NJ 08805.","Inspection by the Fire Marshal or designee for compliance with Borough regulations, including Property Maintenance (Chapter 17), and construction and fire codes","Application pages 1 and 2 complete for every unit in the building on a sale (buyer name and contact, property type, bedrooms, baths, occupants)","Smoke alarms, carbon monoxide alarms and fire extinguisher compliance (the certificate name still includes a fire extinguisher)","Hot water heater must be grounded (re-sales)","House address must be on the front of the house and visible from the road (re-sales)","Affidavits are no longer accepted"]$j$::jsonb, $j$[{"label":"CSACMFEHC (resale/re-rent housing and smoke/CO certificate), per inspection","amount":"$125"},{"label":"Rescheduling a no-show inspection","amount":"$75"}]$j$::jsonb, $t$https://boundbrook-nj.org/wp-content/uploads/2022/03/Re-rent-Sale-CO-Application-No-affidavit.pdf$t$, $t$https://boundbrook-nj.org/permits-and-forms/$t$, $j$[{"url":"https://boundbrook-nj.org/wp-content/uploads/2022/03/Re-rent-Sale-CO-Application-No-affidavit.pdf","label":"Official source (boundbrook-nj.org)"},{"url":"https://ecode360.com/32680961","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certificate of Smoke Alarm Carbon Monoxide Fire Extinguisher Housing Compliance (formerly Re-Rent or Re-Sale)$t$, $t$e910be6db8309d2d40c33e9895fff6d1cfc376a6788be9822f35ab3abce8a98f$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1804.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1804.json$t$, true),
  ($t$1804$t$, $t$Bound Brook Borough$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Bound Brook Bureau of Fire Prevention (town fire bureau)","Contact: Erik J Mickelsen, Fire Official · (732) 356-0833 · emickelson@boundbrook-nj.org","Apply: Pay before scheduling; certificate issued within six business days of the inspection if compliant. No tiered short-notice fee is published.","How to apply: Same application as the resale certificate (Application for CSACMFEHC); one inspection covers both.","Fire official in the NJ state directory (town), updated 5/27/2026: Erik J Mickelsen · (732) 356-0833 · emickelson@boundbrook-nj.org","Smoke alarms and carbon monoxide alarms per the Uniform Fire Code (checklist on pages 3 and 4 of the Borough application, which are images)","Fire extinguisher (still in the certificate name and ordinance; the state dropped it from the sale certificate in February 2025)","Hot water heater grounded and address visible from the road (Borough re-sale items checked at the same inspection)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSACMFEHC (resale/re-rent housing and smoke/CO certificate), per inspection","amount":"$125"},{"label":"Rescheduling a no-show inspection","amount":"$75"}]$j$::jsonb, $t$https://boundbrook-nj.org/wp-content/uploads/2022/03/Re-rent-Sale-CO-Application-No-affidavit.pdf$t$, $t$https://boundbrook-nj.org/permits-and-forms/$t$, $j$[{"url":"https://boundbrook-nj.org/wp-content/uploads/2022/03/Re-rent-Sale-CO-Application-No-affidavit.pdf","label":"Official source (boundbrook-nj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$BOROUGH OF BOUND BROOK ­ Bureau of Fire Prevention - Application for CSACMFEHC$t$, $t$3a728640033bd6a7e713b0822294c1b16ee52d870ba05829667164bffbe3f690$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1804.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1804.json$t$, true),
  ($t$1807$t$, $t$Far Hills Borough$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Construction Records Clearance (CRC)$t$, $j$["Issued by: Borough of Far Hills Construction / Code Enforcement Office","Contact: Stephen Mahoney, Code Enforcement Officer · 908.234.0611 ext. 26 · smahoney@farhillsnj.org","Apply: Fee depends on business days before closing or change of occupancy: more than 10 business days for the lowest fee.","How to apply: Fill out the Construction Records Clearance Application (closing date required) and submit it with the fee to the Code Enforcement Office, Borough Hall, 6 Prospect Street, Far Hills, or contact Code Enforcement Officer Stephen Mahoney (smahoney@farhillsnj.org, 908.234.0611 ext. 26). The certificate is mailed or held for pickup. The smoke/CO certificate is a separate application to the Fire Official.","Records review before the sale of any residential structure (Ordinance 2020-14)","Application lists closing date (required), year built, swimming pool and pool fence, finished basement, and any second kitchen, basement, pool house or similar","Office checks for open construction permits, open zoning permits, certificates of occupancy/approvals issued, and zoning approval","The CRC may be approved, approved with conditions, or denied","Also: Open construction and zoning permits: The Construction Records Clearance review checks for open construction permits, open zoning permits, and whether COs or approvals were issued for work on the property."]$j$::jsonb, $j$[{"label":"Construction Records Clearance, request more than 10 business days before change of occupancy or closing","amount":"$45.00"},{"label":"Construction Records Clearance, request within 10 business days","amount":"$90.00"},{"label":"Construction Records Clearance, request within 4 business days","amount":"$161.00"},{"label":"Duplicate Construction Records Clearance certificate","amount":"$25.00"}]$j$::jsonb, $t$https://www.farhillsnj.org/Construction%20Records%20Clearance%20Application%20r.%2092420.pdf$t$, $t$https://www.farhillsnj.org/how_do_i_/sell_my_home/index.php$t$, $j$[{"url":"https://www.farhillsnj.org/how_do_i_/sell_my_home/index.php","label":"Official source (farhillsnj.org)"},{"url":"https://www.farhillsnj.org/Construction%20Records%20Clearance%20Application%20r.%2092420.pdf","label":"Official source (farhillsnj.org)"}]$j$::jsonb, $t$There are two requirements for selling a home in the Borough of Far Hills.$t$, $t$cba9b5134d617223adb0fa79cc9623063bac10b95eca87335dd97b84ecee1fc6$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1807.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1807.json$t$, true),
  ($t$1807$t$, $t$Far Hills Borough$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Far Hills Fire Official (Far Hills Boro Fire Prevention) (town fire bureau)","Contact: Steven Dill, Fire Official · 908.234.0611 ext. 29 · sdill@farhillsnj.org","Apply: Fee depends on business days before the change of occupancy or ownership: more than 10 business days for the lowest fee. Closing date is required on the application.","How to apply: Fill out the Smoke Detector/Carbon Monoxide Application (check SALE, give the closing date and note any central alarm or secondary power) and submit it with a check payable to Borough of Far Hills to the Fire Official, Steven Dill (sdill@farhillsnj.org, 908.234.0611 ext. 29), Borough Hall, 6 Prospect Street. The fee must accompany the application. A failed inspection can mean added re-inspection fees.","Fire official in the NJ state directory (town), updated 1/21/2026: Steven T Dill · (908) 234-0611 · sdill@farhillsnj.org","Smoke alarms on each level and within 10 feet of each separate sleeping area; basement alarms near the stairway to the floor above; listed to UL 217 (combination smoke/CO allowed)","Ten-year sealed battery alarms where none exist or when replacing battery units; original AC-powered alarms may not be replaced with battery alarms","Replace smoke alarms older than 10 years","Age-based rules: before 1977 battery alarms on each level and near bedrooms; 1977 to 8-5-1984 AC alarms outside sleeping areas and basement plus battery on first floor; 8-6-1984 to 4-30-1993 interconnected AC alarms on each level; 5-1-1993 on, interconnected AC alarms in each bedroom and on each level with battery backup","Homes with a monitored NFPA 72 system instead of AC smoke alarms need an inspection and certificate of compliance from a certified alarm contractor or electrician","Carbon monoxide alarms (UL 2034) within 10 feet of each separate sleeping area; replace when 5 to 7 years old per manufacturer","Secondary power source label (such as CAUTION: MULTIPLE SOURCES OF POWER, not handwritten) within 18 inches of the main electrical panel and electric meter; the office can supply labels","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector/CO certificate, application more than 10 business days before change of occupancy","amount":"$45.00"},{"label":"Application fewer than 10 business days before","amount":"$70.00"},{"label":"Application fewer than 4 business days before","amount":"$125.00"}]$j$::jsonb, $t$https://www.farhillsnj.org/Smoke%20Detector-CO%20Alarm%20Permit%20Application%20r.%204-2025%20-%20FILLABLE.pdf$t$, $t$https://www.farhillsnj.org/how_do_i_/sell_my_home/index.php$t$, $j$[{"url":"https://www.farhillsnj.org/how_do_i_/sell_my_home/index.php","label":"Official source (farhillsnj.org)"},{"url":"https://www.farhillsnj.org/Smoke%20Detector-CO%20Alarm%20Permit%20Application%20r.%204-2025%20-%20FILLABLE.pdf","label":"Official source (farhillsnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$the owner shall obtain a certificate of smoke detector and carbon monoxide alarm compliance (CSDCMAC) with the Borough Fire Official per$t$, $t$307df5477913295aefa05ee8b25f7086b44870fa065a1f5fcc1f645368ef047f$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1807.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1807.json$t$, true),
  ($t$1808$t$, $t$Franklin Township$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Franklin Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Barry Wilbur, Construction Official · 732-873-7283","How to apply: No Township resale Certificate of Occupancy or continued occupancy inspection for selling a home. The only Township certificate needed is the smoke alarm and carbon monoxide alarm certificate (CSACMAC) from the Fire Prevention Department (see fire certificate). The Certificate of Continued Building Compliance (CCBC) applies to commercial sales and new commercial tenants."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.franklintwpnj.org/departments/construction-code$t$, $j$[{"url":"https://www.franklintwpnj.org/departments/construction-code","label":"Official source (franklintwpnj.org)"},{"url":"https://ecode360.com/6343588","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Certificate Continued Occupancy inspection is not required in Franklin Township when selling a residential home; what is required is an inspection from the Fire Prevention Department$t$, $t$735182b6537c9edf7304a77172d9f23bf1cace05c5d2b64d7c41d27438c33c8d$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":13,"q_ok":1,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/1808.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1808.json$t$, true),
  ($t$1808$t$, $t$Franklin Township$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Franklin Township Fire Prevention Department (town fire bureau)","Contact: John J. Hauss, Director of Fire Prevention · 732-873-2500 ext. 6303 · john.hauss@twp.franklin.nj.us","Apply: One week (7 days) notice from receipt of the application and fee; otherwise the rush fee applies. Inspections are Tuesdays and Thursdays, 8:00 am to 5:00 pm. The certificate is not transferable, and a new application is needed if the sale does not happen within six months.","How to apply: Download and print the Smoke Detector Application from the Fire Prevention page, fill it out and submit it with the prepaid fee (checks payable to 'Franklin Township') to the Fire Prevention Department, 475 DeMott Lane, Somerset. The inspection is scheduled only after the completed application and fee are received.","Fire official in the NJ state directory (town), updated 1/21/2026: John J Hauss · (732) 873-2500 · john.hauss@twp.franklin.nj.us","Smoke alarm on every level and within 10 feet of every bedroom door; alarms must be less than 10 years old","Battery-only smoke alarms must be 10-year sealed units; electric alarms may not be replaced with battery alarms, and the required type depends on when the house was built or renovated","Carbon monoxide alarm (UL 2034) in the hallway within 10 feet of every bedroom door on sleeping levels, unless the home has no fuel-burning appliances or attached garage","Homes with a residential sprinkler system need a satisfactory inspection report from a NJ licensed contractor","Homes with a secondary power source (generator, solar, battery storage) need 'CAUTION: MULTIPLE SOURCES OF POWER' labels within 18 inches of the main panel and electric meter","No fire extinguisher is listed on the Township's application or guide","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, initial inspection plus one reinspection","amount":"$50.00"},{"label":"Each additional reinspection","amount":"$50.00"},{"label":"Rush, less than one week (7 days) notice","amount":"$150.00"},{"label":"No-show inspection","amount":"$50.00"},{"label":"Residential fire suppression (sprinkler) system inspection at the time of the smoke/CO inspection","amount":"$25.00"}]$j$::jsonb, $t$https://www.franklintwpnj.org/home/showpublisheddocument/30823/638816112785830000$t$, $t$https://www.franklintwpnj.org/departments/fire-prevention$t$, $j$[{"url":"https://ecode360.com/6342791","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/6342795","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/6342807","label":"Official source (ecode360.com)"},{"url":"https://www.franklintwpnj.org/home/showpublisheddocument/30823/638816112785830000","label":"Official source (franklintwpnj.org)"},{"url":"https://www.franklintwpnj.org/departments/fire-prevention","label":"Official source (franklintwpnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any Use Group R-3, R-4 or R-5 structure in Franklin Township is sold, leased, or otherwise made subject to a change of occupancy for residential purposes, the owner shall obtain a certificate of smoke detector and carbon monoxide alarm compliance (CSDCMAC) compliance evidencing compliance with N.J.A.C. 5:70-4.19, from the Franklin Township Department of Fire Prevention.$t$, $t$75dd886060705ef6d251cc831ac77224933c9b171e5bfc31ef27f39634e23195$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":13,"q_ok":1,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/1808.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1808.json$t$, true),
  ($t$1810$t$, $t$Hillsborough Township$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Hillsborough Township. Confirm with the office if the buyer's lender or title company asks.","Contact: (908) 369-4313","How to apply: No resale Certificate of Occupancy. The Hillsborough Building Department does not issue a CO for the resale of a residential property. Call the Fire Safety office to schedule the smoke detector certification (see fire certificate) and check with the Building Department that there are no open permits.","Also: Open permits: The Township advises sellers to verify with the Building Department that there are no open permits before selling."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://hillsboroughnj.gov/departments/construction$t$, $j$[{"url":"https://hillsboroughnj.gov/news-announcements/708-no-c-o-needed-for-residential-resale","label":"Official source (hillsboroughnj.gov)"},{"url":"https://hillsboroughnj.gov/news-announcements/587-do-you-need-a-certificate-of-occupancy-for-resale-of-residential-property","label":"Official source (hillsboroughnj.gov)"},{"url":"https://hillsboroughnj.gov/news-announcements/1163-selling-your-home","label":"Official source (hillsboroughnj.gov)"}]$j$::jsonb, $t$The Hillsborough Building Department does not issue a CO for the resale of a residential property.$t$, $t$497a7c9cb78a76cd81d304ab47adf4547d5b50deb97525c692577acf9fc73279$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":9,"q_ok":4,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1810.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1810.json$t$, true),
  ($t$1810$t$, $t$Hillsborough Township$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hillsborough Fire District, Bureau of Fire & Safety (Hillsborough Bureau of Fire Safety) (fire district)","Contact: John Yanko, Fire Official (NJ DCA fire directory) · 908-271-5140 · FireSafety@htfd.us","Apply: Fee depends on how many business days before the change of occupant the request is received (more than 10 business days for the lowest fee, per the Township code seen in search results). The fee covers the first inspection and one reinspection.","How to apply: Apply on the Hillsborough Bureau of Fire Safety form and call the Fire Safety office to schedule the smoke detector certification inspection. Office: 48 East Mountain Road, Hillsborough, NJ 08844, open Monday to Friday 8:00 AM to 4:00 PM.","Fire official in the NJ state directory (fire district), updated 6/4/2026: John Yanko · (908) 369-5856 · jyanko@htfd.us","Smoke alarms and carbon monoxide alarms for one and two family dwellings per the NJ Uniform Fire Code","No fire extinguisher needed since the 2025 state change (Hillsborough Fire District notice, February 2, 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, request received more than 10 business days before the change of occupant","amount":"$50"},{"label":"Request received four to 10 business days before the change of occupant","amount":"$90"},{"label":"Request received fewer than four business days before the change of occupant","amount":"$160"},{"label":"Each additional reinspection after the first reinspection","amount":"$35"}]$j$::jsonb, null, $t$https://hillsboroughfiresafety.com/smoke-detector-certification-inspections/$t$, $j$[{"url":"https://hillsboroughfiresafety.com/","label":"Official source (hillsboroughfiresafety.com)"},{"url":"https://hillsboroughfiresafety.com/news/smoke-alarm-certification-requirement-change/","label":"Official source (hillsboroughfiresafety.com)"},{"url":"https://hillsboroughnj.gov/news-announcements/587-do-you-need-a-certificate-of-occupancy-for-resale-of-residential-property","label":"Official source (hillsboroughnj.gov)"},{"url":"https://ecode360.com/10253736","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$FireSafety@htfd.us$t$, $t$f641492ac7d7410a6ff4586c33d47180246aff6a5b7c20d9b1ad7bdbf8d6c5c3$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":9,"q_ok":4,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1810.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1810.json$t$, true),
  ($t$1811$t$, $t$Manville Borough$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate for Home Sale$t$, $j$["Issued by: Borough of Manville Division of Code Enforcement (housing inspector), on a combined application with the Bureau of Fire Safety smoke/CO certificate","Contact: Heather Haney, Technical Assistant to Construction Official · 908-725-9478 ext. 117 · hhaney@manvillenj.org","How to apply: Fill out the combined application (pick up at the Construction Department window in Borough Hall or download it), pay by check payable to Borough of Manville, and make the inspection appointment by calling (908) 725-9478 Ext. 117. Division of Code Enforcement, 325 North Main Street, Manville, NJ 08835.","Owner or agent applies on the Borough's combined Application for Smoke Alarm/Carbon Monoxide Alarm/Portable Fire Extinguisher Compliance and Certificate for Home Sale","Inspection appointment made by phone with the office","Housing inspector signs off on the home sale certificate; Fire Marshal signs off on the smoke/CO part","Application asks for buyer, owner's attorney, closing date, year built and whether the home is owner occupied, rental or bank owned"]$j$::jsonb, $j$[{"label":"Certificate for Home Sale","amount":"$50.00"}]$j$::jsonb, $t$https://www.manvillenj.org/DocumentCenter/View/7595/CSDCMAC-Application-2025$t$, $t$https://www.manvillenj.org/597/Code-Enforcement$t$, $j$[{"url":"https://www.manvillenj.org/DocumentCenter/View/7595/CSDCMAC-Application-2025","label":"Official source (manvillenj.org)"},{"url":"https://www.manvillenj.org/597/Code-Enforcement","label":"Official source (manvillenj.org)"}]$j$::jsonb, $t$APPLICATION FOR SMOKE ALARM/CARBON MONOXIDE ALARM/ PORTABLE FIRE EXTINGUISHER COMPLIANCE AND CERTIFICATE FOR HOME SALE$t$, $t$dbb8596806a07586efea0b11ab10c8aa85cb283aaa4ac183fefee0d2212e7868$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1811.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1811.json$t$, true),
  ($t$1811$t$, $t$Manville Borough$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Manville Bureau of Fire Safety (Office of the Fire Marshal) (town fire bureau)","Contact: Rick Connolly, Fire Marshal · 908-725-9478 ext. 112 · RConnolly@manvillenj.org","Apply: Fee depends on business days before the change of occupant: more than 10 business days for the lowest fee. Certificate is good for six months. Cancellations need 48 hours notice.","How to apply: Use the combined Borough application (Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance plus Certificate for Home Sale), pay by check payable to Borough of Manville, and schedule the inspection by phone. Questions: Fire Marshal, 908-725-9478 ext. 112.","Fire official in the NJ state directory (town), updated 1/29/2026: Richard J Connolly III · (908) 725-9478 · rconnolly@manvillenj.org","10-year sealed single-station smoke alarms (Borough says no other battery alarms accepted); hardwired interconnected alarms must all sound when one is tested and cannot be swapped for battery units","Smoke alarm on every level including the basement (at the base of basement steps), near steps to the second floor, at the top of fixed attic stairs, and within 10 feet of bedrooms","Carbon monoxide alarm near sleeping rooms in homes with a fuel-burning appliance, fireplace or attached garage (all-electric homes with none of these are exempt)","Portable 2A-10B:C fire extinguisher within 10 feet of the kitchen in the path of egress, mounted with bracket, serviced/tagged within 12 months or with a recent receipt, manual left for the buyer (Borough Ordinance still requires it)","Home security alarm systems are not tested","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher certificate, request more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Request 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Request fewer than 4 business days before change of occupant","amount":"$161.00"},{"label":"Reinspection","amount":"$35.00"}]$j$::jsonb, $t$https://www.manvillenj.org/DocumentCenter/View/7595/CSDCMAC-Application-2025$t$, $t$https://www.manvillenj.org/578/Bureau-of-Fire-Safety$t$, $j$[{"url":"https://www.manvillenj.org/578/Bureau-of-Fire-Safety","label":"Official source (manvillenj.org)"},{"url":"https://www.manvillenj.org/DocumentCenter/View/6595/2023-1306-Fire-Safety-Ordinance-","label":"Official source (manvillenj.org)"},{"url":"https://www.manvillenj.org/DocumentCenter/View/7595/CSDCMAC-Application-2025","label":"Official source (manvillenj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Bureau of Fire Safety also enforces the Smoke Alarm Carbon Monoxide Alarm Portable Fire Extinguisher Law (CSACMAPFEC) on the sale or change of tenancy of a one or two family residence .$t$, $t$527dbf68ec11dd62da8e1df0248926fbce1ee2dffcca580f0074ea57786273ef$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":9,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1811.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1811.json$t$, true),
  ($t$1814$t$, $t$North Plainfield Borough$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Municipal Certificate of Code Compliance (MCC)$t$, $j$["Issued by: Borough of North Plainfield Department of Health, Housing & Property (Property Maintenance / Zoning, Code Compliance Officer)","Contact: Kenneth Capobianco, Code Enforcement Officer (908-769-2913) · 908-769-2915 · kcapobianco@northplainfieldnj.gov","Apply: Schedule the inspection at least two weeks before closing. The code says the inspection is made within 10 days of the application and fee. Inspections are generally Tuesday and Wednesday 10am to noon and Thursday 1pm to 3pm.","How to apply: Get the MCC application from the Property Maintenance / Zoning page or the Construction/Zoning window at Borough Hall, 263 Somerset Street, and submit it with the fee (exact cash, certified check or money order) at the Property Maintenance window. The inspection is scheduled for the next available date; someone must let the inspector in, and a missed inspection needs a paid reinspection.","Inspection for illegal conversions to two-family or multi-family use, illegal rooming units, and living units in basements, attics or other non-habitable spaces","Construction done without permits (sheds, pools, decks, stoves, water heaters, furnaces, additions) must get retroactive permits and inspections; open construction permits must be closed","10-year sealed battery smoke detectors (or the hardwired type required when the home was built) on each floor and within 10 feet of any bedroom","Carbon monoxide detectors within 10 feet of any sleeping area","Handrails on stairs of three or more risers, returned to the wall","Fire extinguisher within 10 feet of the kitchen (form still lists it)","Vacant house fees paid, taxes and sewer charges addressed, and liens or special charges to the Borough paid","Certificate is issued in the name of the new owner before closing","Also: Vacant house fees, taxes, sewer charges and liens: Vacant house fees must be paid, taxes and sewer charges addressed, and liens or special charges to the Borough paid before the MCC is issued.","Also: Open permits and work without permits: Open construction permits must be closed, and work done without permits needs retroactive permits and inspections before the MCC is issued.","Also: Lead inspection (pre-1978 rental homes only): If a 1-2 family rental built before 1978 has no record of the required lead inspection, it is required as a condition of the MCC on sale; $120 per unit fee for each lead certificate submitted.","Also: Statement in agreement of sale: Sellers must include in the agreement of sale a statement on whether any outstanding property maintenance notice or order exists."]$j$::jsonb, $j$[{"label":"MCC, single family","amount":"$100.00"},{"label":"MCC, two family","amount":"$200.00"},{"label":"MCC reinspection, per unit (application form)","amount":"$50.00"},{"label":"Certificate of Municipal Code Compliance, per dwelling unit (Borough code)","amount":"$100.00"}]$j$::jsonb, $t$https://www.northplainfieldnj.gov/government/documents/resident-forms/department-documents/zoning-board-of-adjustment-documents/44-municipal-certificate-of-compliance-mcc/file$t$, $t$https://www.northplainfieldnj.gov/departments/property-maintenance-zoning$t$, $j$[{"url":"https://www.northplainfieldnj.gov/departments/property-maintenance-zoning","label":"Official source (northplainfieldnj.gov)"},{"url":"https://ecode360.com/35425565","label":"Official source (ecode360.com)"},{"url":"https://www.northplainfieldnj.gov/government/documents/resident-forms/department-documents/zoning-board-of-adjustment-documents/44-municipal-certificate-of-compliance-mcc/file","label":"Official source (northplainfieldnj.gov)"}]$j$::jsonb, $t$If you are selling your residential property, you must apply for a Municipal Certificate of Compliance (MCC).$t$, $t$fe3b2610288070b6f986e95ce54c0f06e3158a19476143d333e23b10a97c1606$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1814.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1814.json$t$, true),
  ($t$1814$t$, $t$North Plainfield Borough$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of North Plainfield Department of Health, Housing & Property (smoke/CO check is part of the Municipal Certificate of Code Compliance) (town fire bureau)","Contact: 908-769-2915","Apply: Schedule at least two weeks before closing (MCC inspection).","How to apply: There is no separate smoke/CO application for 1-2 family sales. The MCC application doubles as the smoke detector and carbon monoxide certificate application; the housing inspector checks the alarms during the MCC inspection.","Fire official in the NJ state directory, updated 1/9/2026: Steven Dill · (908) 769-2934 · sdill@northplainfieldnj.gov","Smoke alarms on every level (including the basement) and within 10 feet of bedroom doors; battery units must be 10-year sealed; required type depends on when the home was built (1978-1983 hardwired; 1984-1990 interconnected with battery backup; 1991 on also in each bedroom)","Electric smoke detectors may not be replaced with battery units; defective interconnected detectors must be replaced with compatible units","Carbon monoxide alarm on each sleeping level, in the hallway near each bedroom door","Two family homes: smoke detectors on each landing of common hallways and stairs","Portable fire extinguisher (2A:10B:C, 10 lbs or less) mounted within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.northplainfieldnj.gov/government/documents/resident-forms/department-documents/zoning-board-of-adjustment-documents/44-municipal-certificate-of-compliance-mcc/file$t$, $t$https://www.northplainfieldnj.gov/departments/property-maintenance-zoning$t$, $j$[{"url":"https://www.northplainfieldnj.gov/government/documents/resident-forms/department-documents/zoning-board-of-adjustment-documents/44-municipal-certificate-of-compliance-mcc/file","label":"Official source (northplainfieldnj.gov)"},{"url":"https://fire.northplainfieldnj.gov/fire-prevention/fire-prevention-information","label":"Official source (fire.northplainfieldnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certificate of Compliance NJAC 5:18, 2.20 (Smoke Detectors)$t$, $t$9a01f59815fdedfbbcee37360d954744410b43f135755410f4363cd6a2196718$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1814.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1814.json$t$, true),
  ($t$1819$t$, $t$South Bound Brook Borough$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Legal Use (combined with Smoke Detector and Carbon Monoxide Alarm Compliance)$t$, $j$["Issued by: Borough of South Bound Brook Bureau of Fire Prevention (Fire Prevention Officer)","Contact: Ryan Pinnella, Fire Marshal · 732-356-0258 x 105 · rpinnella@southboundbrook.com","Apply: The Bureau asks for at least two weeks' notice from receipt of the application and fee. Inspections are Tuesdays and Thursdays between 4pm and 6pm, by appointment.","How to apply: Download the Certificate of Legal Use application from the Building Department page, fill in the property, new owner, present owner, contact and number of units, and send it with a check for $150.00 per unit to Fire Prevention, 2 Main Street, South Bound Brook, NJ 08880 (732-356-0258 x 105). Appointments are required.","Inspection for a Certificate of Legal Use for continued use of the property, requested with the new owner's name, block and lot, number of dwelling units and an appointment date","Same inspection covers smoke alarms, carbon monoxide alarms and the secondary power source label (see fire certificate)"]$j$::jsonb, $j$[{"label":"Certificate of Legal Use / smoke and CO compliance inspection, per unit","amount":"$150.00"},{"label":"Re-inspection","amount":"$100.00"}]$j$::jsonb, $t$https://sbbnj.com/wp-content/uploads/Documents/BuildingDept/CertificateOfLegalUseRev08_2026.pdf$t$, $t$https://sbbnj.com/departments/building-department/$t$, $j$[{"url":"https://sbbnj.com/wp-content/uploads/Documents/BuildingDept/CertificateOfLegalUseRev08_2026.pdf","label":"Official source (sbbnj.com)"},{"url":"https://sbbnj.com/departments/building-department/","label":"Official source (sbbnj.com)"}]$j$::jsonb, $t$I hereby request you to make an inspection for a Certificate of Legal Use for continued use of the above property.$t$, $t$c21d1c01a10453727c9aea6107f033ce4d2427fdde7149f513e75772d2a2cc58$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":9,"q_ok":1,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1819.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1819.json$t$, true),
  ($t$1819$t$, $t$South Bound Brook Borough$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of South Bound Brook Bureau of Fire Prevention (town fire bureau)","Contact: Ryan Pinnella, Fire Marshal · 732-356-0258 x 105 · rpinnella@southboundbrook.com","Apply: At least two weeks' notice from receipt of the application and fee. Inspections Tuesdays and Thursdays 4pm to 6pm, by appointment.","How to apply: Send the Certificate of Legal Use application with the fee to Fire Prevention, 2 Main Street, South Bound Brook (732-356-0258 x 105, rpinnella@southboundbrook.com) at least two weeks ahead and book a Tuesday or Thursday 4pm to 6pm appointment. Read the guidelines first; a failed inspection costs $100.00 to re-inspect.","Fire official in the NJ state directory, updated 5/27/2025: Ryan Pinnella · (732) 356-0258 · rpinnella@southboundbrook.com","Smoke alarms per the age of the home (Table B): before January 1977 10-year sealed battery alarms on all levels; later homes need electric, then interconnected, then interconnected with battery backup in sleeping areas, matching original construction","Replace smoke alarms older than 10 years or past the replacement date; electric alarms may not be replaced with battery alarms; defective interconnected alarms must be replaced with compatible units","Basement and non-sleeping levels: alarm near the stairway to the floor above; two-family common hallways and stairways need alarms at each landing","Alarms listed to UL 217 or ETL, mounted flush, not painted, not within 5 feet of a kitchen or 3 feet of a bathroom door, fan or air vent","Homes relying on a fire alarm system need a contractor report showing it is fully operational; the Bureau will not test alarm systems","Carbon monoxide alarms (UL 2034) on sleeping levels within 10 feet outside every sleeping area","Secondary power source label (such as CAUTION: MULTIPLE SOURCES OF POWER, not handwritten) within 18 inches of the main panel and meter if the home has a secondary power source; labels available at the counter","Portable fire extinguisher, 2A-10B:C, no more than 10 lbs, mounted within 10 feet of the kitchen (older 2020 instruction sheet still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Legal Use / smoke and CO alarm compliance inspection, per unit","amount":"$150.00"},{"label":"Re-inspection","amount":"$100.00"}]$j$::jsonb, $t$https://sbbnj.com/wp-content/uploads/Documents/BuildingDept/CertificateOfLegalUseRev08_2026.pdf$t$, $t$https://sbbnj.com/departments/building-department/$t$, $j$[{"url":"https://sbbnj.com/wp-content/uploads/Documents/BuildingDept/CertificateOfLegalUseRev08_2026.pdf","label":"Official source (sbbnj.com)"},{"url":"https://sbbnj.com/wp-content/uploads/Documents/BuildingDept/Instructions-CLU.pdf","label":"Official source (sbbnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Bureau requires a minimum of two (2) weeks' notice from the time we receive the application and fee.$t$, $t$5bb11d0da579eccdaf9e856eb256f85d7fa590f8cc4381f8b7f362d46229eda2$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":9,"q_ok":1,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/1819.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1819.json$t$, true),
  ($t$1820$t$, $t$Warren Township$t$, $t$SOMERSET$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance Certificate (CRCC)$t$, $j$["Issued by: Warren Township Construction Office (Construction Official)","Contact: Jeffrey Heiss, Construction Official/Building Subcode · 908-753-8000 ext. 240 · jheiss@warrennj.org","Apply: Apply at least 10 days before the change of ownership; filing less than 10 days before the certificate is needed costs the expedited fee.","How to apply: Fill out the Construction Records Clearance Certificate application (Township Forms & Permits page) and submit it with the fee to the Construction Office, 46 Mountain Boulevard, Warren (temporary in-person location: Municipal Complex, 3 Mountainview Road). Questions: 908-753-8000 ext. 240, 241 or 242.","Valid for: 90 days, and only for permits issued before the CRCC application","Records check (not a physical inspection) for open construction permits","If permits are open, all final inspections and approvals must be done and certificates issued before the CRCC; the applicant must close all permits and notify the office","Application must list the closing date","Exempt if there is no change in physical occupancy for deed corrections, transfers between spouses, new construction needing a CO, estate distributions, refinancing and similar transfers","Also: Open construction permits: All open construction permits must be closed before the Construction Records Clearance Certificate is issued."]$j$::jsonb, $j$[{"label":"CRCC, request more than 10 calendar days before closing","amount":"$75.00"},{"label":"CRCC, expedited, request within 10 calendar days of closing","amount":"$150.00"},{"label":"CRCC application fee (Township code)","amount":"$75"},{"label":"CRCC expedited review (Township code)","amount":"$150"}]$j$::jsonb, $t$https://warrennj.org/DocumentCenter/View/9091/CRCC-application-2024-PDF$t$, $t$https://warrennj.org/153/Construction-Code$t$, $j$[{"url":"https://ecode360.com/45379552","label":"Official source (ecode360.com)"},{"url":"https://warrennj.org/DocumentCenter/View/9091/CRCC-application-2024-PDF","label":"Official source (warrennj.org)"},{"url":"https://warrennj.org/411","label":"Official source (warrennj.org)"},{"url":"https://warrennj.org/153/Construction-Code","label":"Official source (warrennj.org)"}]$j$::jsonb, $t$A CRCC shall be required prior to the sale of any residential or commercial structure.$t$, $t$7a6625cca4dfc35456508c9311cb2205710c615ce24742b55a9f6fe6cf986c52$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1820.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1820.json$t$, true),
  ($t$1820$t$, $t$Warren Township$t$, $t$SOMERSET$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Warren Township Fire Prevention Bureau (Fire Marshal's Office, Warren Township Fire Department) (town fire bureau)","Contact: Meagan Rivenbark, Fire Secretary (Fire Marshal: Al Shjarback, ext. 259, ashjarback@warrennj.org) · 908-753-8000 ext. 274 · mrivenbark@warrennj.org","Apply: Fee depends on when the request is made: more than 10 business days before the change of occupant for the lowest fee (per the application). No specific inspection dates or times are given; the inspector coordinates the inspection. The inspector waits only 10 minutes; a missed inspection forfeits the fee.","How to apply: Print the Application for Certificate of Smoke Detector, Carbon Monoxide and Portable Fire Extinguisher Compliance, then email it to Fire Secretary Meagan Rivenbark (mrivenbark@warrennj.org) or mail or drop it off at Town Hall. Pay by credit card through MuniciPay (smoke detector applications only), or by cash or check payable to Warren Township.","Fire official in the NJ state directory, updated 2/6/2026: Alfred E Shjarback · (908) 753-8000 · ashjarback@warrennj.org","Smoke detectors on every level (basement, first and second floors) and in every separate sleeping area; basement detector at the bottom of the basement stairs; detectors over 10 years old must be replaced","Battery-only smoke and CO units must be 10-year sealed battery models","Carbon monoxide alarms (UL 2034) within 10 feet of bedroom doors; CO alarms over 7 years old must be replaced unless the manufacturer says otherwise","Portable fire extinguisher (2A:10B:C, no more than 10 lbs) mounted within 10 feet of the kitchen, less than one year old or tagged within one year (Township form and code still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher certificate, request more than 10 business days before the change of occupant","amount":"$50.00"},{"label":"Request fewer than 10 business days before the change of occupant","amount":"$80.00"},{"label":"Reinspection before the change of occupant","amount":"$35.00"}]$j$::jsonb, $t$https://warrennj.org/DocumentCenter/View/346/Application-for-Certificate-of-Smoke-Detector-Carbon-Monoxide-and-Portable-Fire-Extinguisher-Compliance-PDF$t$, $t$https://warrennj.org/193/Residential-Smoke-Detector-Inspection-In$t$, $j$[{"url":"https://warrennj.org/193/Residential-Smoke-Detector-Inspection-In","label":"Official source (warrennj.org)"},{"url":"https://warrennj.org/DocumentCenter/View/346/Application-for-Certificate-of-Smoke-Detector-Carbon-Monoxide-and-Portable-Fire-Extinguisher-Compliance-PDF","label":"Official source (warrennj.org)"},{"url":"https://warrennj.org/DocumentCenter/View/345/Application-for-Certificate-of-Smoke-Detector-Carbon-Monoxide-and-Portable-Fire-Extinguisher-Compliance-Requirements-PDF","label":"Official source (warrennj.org)"},{"url":"https://ecode360.com/35228017","label":"Official source (ecode360.com)"},{"url":"https://warrennj.org/187/Fire-Prevention-Bureau","label":"Official source (warrennj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$For residential smoke detector inspection and permit application questions, please call 908-753-8000, ext. 274$t$, $t$5b7218dc3f16bfdc3a3084b6b3257554aae478559e1d45a26723eba04547ee08$t$, $t$2026-10-03T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-03","approved_on":"2026-10-03","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":5,"fee_bad":0,"fee_unchecked":2,"quotes":14,"q_ok":8,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1820.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-03 and approved in the NJ Resale Certificate Tracker on 2026-10-03. Source: property/data/municipal-requirements/checked/1820.json$t$, true)
